/* -- js/Engine/Audio/AudioCategoryRules.js -- */
const AudioCategoryRules = {
	resolve(id, preset = null) {
		const resolvedPreset = preset || {};
		if (resolvedPreset.category) {
			return resolvedPreset.category;
		}

		switch (resolvedPreset.type) {
			case "music":
				return "music";
			case "ambient":
				return "ambient";
			case "ui":
				return "ui";
			default:
				break;
		}

		if (String(id || '').startsWith('myte_')) return 'entities';
		if (String(id || '').startsWith('footstep_')) return 'footsteps';
		if (['obj_fountain', 'obj_lantern'].some(prefix => String(id || '').startsWith(prefix))) return 'machines';
		if (String(id || '').startsWith('obj_')) return 'world';
		return 'sfx';
	},

	isEnabled(soundManager, category) {
		switch (category) {
			case 'music':
				return soundManager.musicEnabled;
			case 'ambient':
				return soundManager.soundEnabled && soundManager.ambientEnabled;
			case 'footsteps':
				return soundManager.soundEnabled && soundManager.footstepsEnabled;
			default:
				return soundManager.soundEnabled;
		}
	},

	getVolume(soundManager, category) {
		switch (category) {
			case 'music':
				return soundManager.volume.music;
			case 'ambient':
				return soundManager.volume.ambient;
			case 'ui':
				return soundManager.volume.ui;
			case 'footsteps':
				return soundManager.volume.sfx * soundManager.volume.footsteps;
			case 'entities':
			case 'machines':
			case 'notifications':
			case 'world':
			case 'sfx':
			default:
				return soundManager.volume.sfx;
		}
	}
};
;
/* -- js/Engine/Audio/AudioScheduleProfiles.js -- */
const AudioScheduleProfiles = {
	// Each profile defines ambient layers and music for a location type.
	// ambientBase  — always playing in this location
	// ambientDay   — added during daytime hours (7–17)
	// ambientNight — added during night hours (19–4)
	// music*       — music IDs keyed by time window
	_profiles: {
		outside: {
			ambientBase:  ['env_wind'],
			ambientDay:   ['env_birds'],
			ambientNight: ['env_cricket'],
			musicDay:     'music_sunny',
			musicNight:   'music_night',
			musicDefault: 'music_main'
		},
		inside: {
			ambientBase:  ['env_indoor_cozy'],
			ambientDay:   [],
			ambientNight: [],
			musicDay:     'music_sunny',
			musicNight:   'music_night',
			musicDefault: 'music_main'
		}
	},

	_getProfile(location) {
		return this._profiles[location] || this._profiles.outside;
	},

	getMusicForHour(hour, location = 'outside') {
		const p = this._getProfile(location);
		if (!Number.isFinite(hour)) return p.musicDefault;
		if (hour >= 8 && hour < 18) return p.musicDay;
		if (hour >= 20 || hour < 6) return p.musicNight;
		return p.musicDefault;
	},

	getAmbientForHour(hour, location = 'outside') {
		const p = this._getProfile(location);
		const tracks = [...p.ambientBase];
		if (Number.isFinite(hour)) {
			if (hour >= 7 && hour <= 17) tracks.push(...p.ambientDay);
			if (hour >= 19 || hour <= 4) tracks.push(...p.ambientNight);
		}
		return tracks;
	}
};
;
