		  this.state.activeTouchId = newActive.id;
		  this.state.mouse.x = newActive.x;
		  this.state.mouse.y = newActive.y;
		  this.state.mouse.clientX = newActive.clientX;
		  this.state.mouse.clientY = newActive.clientY;
