            health:      stats?.getHealthRatio?.()               ?? 1,
            fun:         stats?.getFunRatio?.()                  ?? 0.5,
            social:      stats?.getSocialRatio?.()               ?? 0.5,
            satiety:     stats?.getSatietyRatio?.()              ?? 0.5,
