    FollowMouseAction,
    FollowObjectAction,
    RunLapsAction,
    CircleAction,
    ZigzagAction,
    PatrolAction,
    WanderAction,
    GuardAction,
    JumpAction,
    GoToObjectAction,

    // State
    DanceAction,
    SimpleSleepAction,
    SleepAction,
    SpinAction,

    // Object interactions
    InspectAction,
    DeepInspectAction,
    InteractObjectAction,
    SurfaceSlotAction,
    NudgeBallAction,
    EatElementAction,
    OpenChestAction,
    CloseChestAction,
    PickFlowerAction,
    TrampleFlowerAction,
    SmellFlowerAction,
    DrinkFromFountainAction,
    WaterPlantAction,
    HarvestAction,
    ShakeTreeAction,
    ChopTreeAction,
    RemoveStumpAction,

    // Social (Myte-to-Myte)
    ShowAffectionAction,
    GreetAction,
    GreetReceiveAction,
    KissAction,
    KissReceiveAction,
    HighFiveAction,
    HighFiveReceiveAction,
    WatchAction,
    ChaseAction,
    EmoteAtAction,
    PlayTagAction,
    PlayFetchAction,

    // Carry
    CarryPickupAction,
    CarryAction,
    BeingCarriedAction,
    CarryPutdownAction,
    PickupItemAction,
    HoldItemAction,
    DropItemAction,
    GiveItemAction,

