/* -- js/Map/GameMap.js -- */
class GameMap {
    constructor(parent, mapData = null) {
        this.parent = parent;
        this.mapData = mapData || {}; // Default empty object if no data provided

        // Core properties
        this.name = null;
        this.displayName = null;
        this.id = null;
        this.dimensions = null;

        // Layer references
        this.layers = {
            background: parent.canvas?.querySelector('.layer.background'),
            groundDecor: parent.canvas?.querySelector('.layer.ground-decor'),
            environmentBack: parent.canvas?.querySelector('.layer.environment-back'),
            objects: parent.canvas?.querySelector('.layer.foreground'),
            environmentFront: parent.canvas?.querySelector('.layer.environment-front'),
            debug: parent.canvas?.querySelector('.layer.debug'),
            particles: parent.canvas?.querySelector('.layer.particles')
        };

        // Systems
        this.zoneManager = null;
        this.gridSystem = null;
        this.particleSystem = null;
        this.environmentManager = null;
        this.renderer = new MapRenderer();
        // Handles a missing gridSystem (falls back to registry scans), so safe
        // to construct before the map initializes.
        this.worldQuery = new WorldQuery(parent?.worldRegistry ?? null, this);

        // Map elements
        this.objects = [];
        this.objectsById = new Map();
        this.droppedItems = [];
        // this.zones = new Map();
        this.spawnPoints = new Map();

        // Cache-bust TMX fetches only while debugging — production transitions
        // should reuse the browser cache.
        this.noCache = Utility.isDebugEnabled();

        // Optimization tracking
        this.activeObjectsCount = 0;
        this.updateFrameSkip = 0;

        // Tile map loader
        this.tileMapLoader = null;

        // Flag to track initialization state
        this.initialized = false;
        this.backgroundReadyPromise = Promise.resolve();
    }

    get container() {
        return this.parent;
    }

    get core() {
        return this.parent?.core || null;
    }

    get ui() {
        return this.parent?.ui || null;
    }

    get camera() {
        return this.parent?.camera || null;
    }

    get mytes() {
        return this.parent?.mytes || [];
    }

    get activeMyte() {
        return this.parent?.activeMyte || null;
    }

    get inventory() {
        return this.parent?.inventory || null;
    }

    get eventManager() {
        return this.core?.eventManager || null;
    }

    get soundManager() {
        return this.core?.soundManager || null;
    }

    getContainerRect() {
        return this.parent?.getContainerRect?.() || {
            left: 0,
            top: 0,
            width: 0,
            height: 0
        };
    }

    getParticleEffectsEnabledSetting() {
        const liveSetting = this.ui?.settingsPanel?.isEffectsEnabled?.();
        if (typeof liveSetting === 'boolean') {
            return liveSetting;
        }

        return this.core?.user?.preferences?.effectsEnabled !== false;
    }

    getTimeOfDayOverlayEnabledSetting() {
        const liveSetting = this.ui?.settingsPanel?.isTimeOfDayOverlayEnabled?.();
        if (typeof liveSetting === 'boolean') {
            return liveSetting;
        }

        return this.core?.user?.preferences?.timeOfDayOverlayEnabled !== false;
    }

    getWeatherEffectsEnabledSetting() {
        const liveSetting = this.ui?.settingsPanel?.isWeatherEnabled?.();
        if (typeof liveSetting === 'boolean') {
            return liveSetting;
        }

        return this.core?.user?.preferences?.weatherEffectsEnabled !== false;
    }

    getZIndex(y, height) {
        return this.parent?.getZIndex?.(y, height) ?? 0;
    }

    getDepthZIndex(sortY, priority = 0) {
        return this.parent?.getDepthZIndex?.(sortY, priority) ?? 0;
    }

    getObjectRenderLayer(object) {
        const layerKey = object?.getActiveRenderLayerKey?.() || object?.getRenderLayerKey?.() || 'objects';
        return this.layers[layerKey] || this.layers.objects || this.layers.background || null;
    }

    getMaxDimensions() {
        return this.parent?.getMaxDimensions?.() || this.dimensions || {
            width: 0,
            height: 0
        };
    }

    transitionToMap(mapId, options = {}) {
        return this.parent?.loadMap?.(mapId, options) || null;
    }

    getObjectById(id) {
        if (id === undefined || id === null) return null;
        return this.objectsById.get(String(id)) || null;
    }

    getMyteById(id) {
        if (id === undefined || id === null) return null;
        return this.mytes.find(myte => String(myte.id) === String(id)) || null;
    }

    checkCollision(entityA, entityB) {
        return this.parent?.checkCollision?.(entityA, entityB) ?? false;
    }

    getMapSourcePath(mapId) {
        return mapId.endsWith('.tmx')
            ? `data/maps/${mapId}`
            : `data/maps/${mapId}.tmx`;
    }

    createMapInitializationError(phase, mapId, attemptedPath, cause) {
        const reason = cause?.message || String(cause || 'Unknown error');
        const error = new Error(`Failed to ${phase} map "${mapId}" from "${attemptedPath}": ${reason}`);
        error.cause = cause;
        return error;
    }


    async initialize(mapId, options = {}) {
        const allowFallback = options.allowFallback === true;
        const mapSourcePath = this.getMapSourcePath(mapId);
        const requestedPath = this.noCache
            ? Utility.preventCache(mapSourcePath)
            : mapSourcePath;

        try {
            Utility.logDebug(`[GameMap] Initializing map: ${mapId}`);

            // Check if the parent and canvas exist
            if (!this.parent) {
                throw new Error('Parent is null or undefined');
            }

            if (!this.parent.canvas) {
                throw new Error('Parent canvas is null or undefined');
            }

            // Initialize particle system first to avoid dependency issues
            Utility.logDebug(`[GameMap] Creating particle system`);
            this.particleSystem = new GameMapParticleSystem(this, {
                effectsEnabled: this.getParticleEffectsEnabledSetting(),
                weatherEnabled: this.getWeatherEffectsEnabledSetting()
            });
            this.particleSystem.start();

            for (const myte of this.mytes || []) {
                if (typeof myte.initParticleEffects === 'function') {
                    myte.initParticleEffects();
                }
            }

            // Initialize tile map loader
            if (!this.tileMapLoader) {
                Utility.logDebug(`[GameMap] Creating new TileMapLoader`);
                this.tileMapLoader = new TileMapLoader(this);
            }

            Utility.logDebug(`[GameMap] Loading TMX from: ${mapSourcePath}`);

            let mapData;
            try {
                mapData = await this.tileMapLoader.loadTileMap(requestedPath);

                if (!mapData) {
                    throw new Error('TMX data is null or undefined');
                }

                Utility.logDebug(`[GameMap] TMX data loaded successfully`);
            } catch (tmxError) {
                throw this.createMapInitializationError('load', mapId, mapSourcePath, tmxError);
            }

            try {
                Utility.logDebug(`[GameMap] Applying TMX data to game map`);
                await this.applyToGameMap(mapData);
                Utility.logDebug(`[GameMap] TMX data applied successfully`);
            } catch (applyError) {
                throw this.createMapInitializationError('initialize', mapId, mapSourcePath, applyError);
            }

            // Reset debug initialization state for GridSystem
            if (this.gridSystem) {
                // Store the current debug mode
                const wasDebugMode = this.gridSystem.debugMode;

                // Reset the initialization flag
                this.gridSystem.debugInitialized = false;

                // If debug mode was on, make sure it gets reinitialized
                if (wasDebugMode) {
                    Utility.logDebug(`[GameMap] Reinitializing GridSystem debug elements`);
                    // Make sure debug mode is off
                    if (this.gridSystem.debugMode) {
                        this.gridSystem.toggleDebug();
                    }

                    // Delay to ensure DOM is ready before reinitializing
                    setTimeout(() => {
                        this.gridSystem.toggleDebug(); // Toggle back on to reinitialize
                    }, 100);
                }
            }

            Utility.logDebug(`[GameMap] Map ${mapId} initialization completed successfully`);
            if (this.gridSystem && document.body.classList.contains('debug') && !this.gridSystem.debugMode) {
                this.gridSystem.toggleDebug();
            }
            this.initialized = true;
            return true;
        } catch (error) {
            this.initialized = false;

            if (allowFallback) {
                try {
                    Utility.warnDebug(`[GameMap] Falling back to default map for initial load of ${mapId}`, error);
                    this.createDefaultMap(mapId);
                    this.initialized = true;
                    return true;
                } catch (fallbackError) {
                    throw this.createMapInitializationError('create fallback', mapId, mapSourcePath, fallbackError);
                }
            }

            throw error;
        }
    }




	async applyToGameMap(mapData) {
		if (!mapData) return;

		// Set dimensions
		this.dimensions = mapData.dimensions;
		this.name = mapData.name;
		this.id = mapData.id;
		this.displayName = mapData.displayName;
		this.description = mapData.description;
		this.location = mapData.environment.location;

		this.gridSystem = new GridSystem(this);
		// One geometry store for every area concept (zones now, lighting rooms
		// below, enclosures later). Must exist before ZoneManager, which registers
		// each zone's geometry into it.
		this.regionManager = new RegionManager(this, {
			cellSize: this.gridSystem?.config?.cellSize ?? 32
		});
		this.zoneManager = new ZoneManager(this);

		Utility.logDebug('Tile map dimensions:', this.dimensions);

		// set canvas
		this.parent.canvas.style.width = `${this.dimensions.width}px`;
		this.parent.canvas.style.height = `${this.dimensions.height}px`;

		// Set background from map
		const bgUrl = await this.tileMapLoader.createMapBackgroundUrl(mapData);
		if (bgUrl) {
			this.setBackground({
				url: bgUrl,
				color: mapData.background?.color || '#f0f0f0'
			});
		} else if (mapData.background) {
			this.setBackground(mapData.background);
		}

		// Generate grid data for the GridSystem
		const gridData = this.tileMapLoader.generateGridData(mapData, {
			cellSize: this.gridSystem?.config?.cellSize || 32,
			collisionLayer: 'Collider'
		});

		// Update the grid system
		if (this.gridSystem) {
			this.gridSystem.updateFromTileGrid(gridData);
		}

		// Add zones
		if (mapData.zones) {
			for (const zoneData of mapData.zones) {
				this.zoneManager.addZone(zoneData);
			}
		}

		// Set spawn points
		if (mapData.spawns) {
			Object.entries(mapData.spawns).forEach(([key, value]) => {
				this.spawnPoints.set(key, value);
			});
		}

        // Add objects
        if (mapData.objects) {
			for (const objData of mapData.objects) {
				const type = objData.type.toUpperCase();

				// Bottom-align: if the tile placeholder in the map is shorter than the
				// object's JSON-defined height, shift Y up so the bottoms coincide.
				let posY = objData.y;
				if (objData.tileHeight > 0) {
					const typeConfig = MapObjectFactory.getTypeConfig(type);
					const jsonHeight = typeConfig?.size?.height;
					if (jsonHeight && jsonHeight !== objData.tileHeight) {
						posY = objData.y + objData.tileHeight - jsonHeight;
					}
				}

				this.addObject(type, objData.variant, objData.x, posY, {
					configOverrides: objData.properties,
					id: objData.id
				});
			}
		}

		// Apply terrain data to pathfinding after objects have been added
		this.applyTerrainToGameMap(mapData);

        this.layers.environmentBack = this.parent.canvas?.querySelector('.layer.environment-back');
        this.layers.environmentFront = this.parent.canvas?.querySelector('.layer.environment-front');
        if (typeof MapEnvironmentManager === 'function') {
            this.environmentManager?.dispose?.();
            this.environmentManager = new MapEnvironmentManager(this);
            await this.environmentManager.initialize(mapData);
        }

        // Rooms exist by now (the environment manager registers them), and objects
        // are placed, so door topology can be derived.
        this.buildDoorRoomTopology();

		// Notify the sound system of this map's audio context and begin proximity polling
		const sm = this.soundManager;
		if (sm) {
			sm.setMapContext({
				location:        mapData.environment.location,
				ambientOverride: mapData.environment.ambientOverride ?? null,
				musicOverride:   mapData.environment.musicOverride   ?? null
			});
			this._startProximitySoundPolling();
		}
	}

	// ── Proximity sound polling ────────────────────────────────────────────────

	_startProximitySoundPolling() {
		this._stopProximitySoundPolling();
		this._proximitySoundInterval = setInterval(() => this._updateProximitySounds(), 500);
	}

	_stopProximitySoundPolling() {
		if (this._proximitySoundInterval != null) {
			clearInterval(this._proximitySoundInterval);
			this._proximitySoundInterval = null;
		}
	}

	_updateProximitySounds() {
		const sm = this.soundManager;
		const myte = this.activeMyte;
		if (!sm || !myte) return;

		// Map<soundId, volumeMultiplier 0–1> — zones give full 1.0, tiles scale by distance
		const sounds = new Map();

		// Water zones take priority — they declare lake vs river explicitly and play at full volume
		if (this.zoneManager) {
			for (const zone of this.zoneManager.getZonesOfType('water_lake')) {
				if (zone.containsMyte(myte)) { sounds.set('env_water_lake', 1.0); break; }
			}
			for (const zone of this.zoneManager.getZonesOfType('water_river')) {
				if (zone.containsMyte(myte)) { sounds.set('env_water_river', 1.0); break; }
			}
		}

		// Fall back to tile scan — volume scales with proximity (louder as you get closer)
		if (sounds.size === 0 && this.gridSystem) {
			const { x, y } = this._myteGroundPos(myte);
			const vol = this._getWaterTileProximity(x, y, 96);
			if (vol > 0) sounds.set('env_water_lake', vol);
		}

		sm.setProximitySounds(sounds);
	}

	/**
	 * Derive which rooms each DOOR/GATE connects, at map load.
	 *
	 * A door sits *in* a wall, so its own centre usually lies in neither room. The
	 * rooms it joins are found by probing outward along both axes from the door's
	 * centre — whichever rooms those probes land in are the ones it connects.
	 *
	 * Doors already toggle grid walkability; this only annotates the topology, so
	 * nothing about movement or collision changes. Stored on the region
	 * (`properties.doors` / `adjacentRooms`) and on the door object (`connectsRooms`).
	 */
	buildDoorRoomTopology() {
		const regionManager = this.regionManager;
		if (!regionManager) return;

		const rooms = regionManager.all('room');
		for (const room of rooms) {
			room.properties.doors = [];
			room.properties.adjacentRooms = [];
		}
		if (rooms.length === 0) return;

		const cellSize = this.gridSystem?.config?.cellSize ?? 32;
		const doors = this.objects.filter(obj => ['DOOR', 'GATE'].includes(obj.type));

		for (const door of doors) {
			const rect = door.getRegionRect?.('collider') ?? {
				x: door.posX, y: door.posY,
				width: door.size?.width ?? 0, height: door.size?.height ?? 0
			};
			const cx = rect.x + (rect.width / 2);
			const cy = rect.y + (rect.height / 2);

			// Probe far enough to clear the wall the door is set into.
			const reach = cellSize * 1.5;
			const probes = [
				{ x: cx, y: cy - reach }, { x: cx, y: cy + reach },
				{ x: cx - reach, y: cy }, { x: cx + reach, y: cy }
			];

			const connected = new Set();
			for (const probe of probes) {
				for (const room of regionManager.regionsAt(probe.x, probe.y, 'room')) {
					connected.add(room);
				}
			}

			const connectedRooms = [...connected];
			door.connectsRooms = connectedRooms.map(room => room.id);

			for (const room of connectedRooms) {
				room.properties.doors.push(door.id);
				for (const other of connectedRooms) {
					if (other !== room && !room.properties.adjacentRooms.includes(other.id)) {
						room.properties.adjacentRooms.push(other.id);
					}
				}
			}
		}
	}

	// Returns the ground-center position of a myte's collider — the best single point
	// for terrain queries (center-X, bottom-Y of the collider, matching actual feet).
	_myteGroundPos(myte) {
		const ox = myte.collider?.offsetX ?? 0;
		const oy = myte.collider?.offsetY ?? 0;
		const cw = myte.collider?.width  ?? myte.size?.width  ?? 0;
		const ch = myte.collider?.height ?? myte.size?.height ?? 0;
		return {
			x: myte.posX + ox + cw / 2,
			y: myte.posY + oy + ch
		};
	}

	// Returns 0 (out of range) to 1 (on top of water) based on closest water tile distance.
	// Uses a linear falloff over the given radius so the sound fades as you walk away.
	_getWaterTileProximity(worldX, worldY, radius) {
		const gs = this.gridSystem;
		if (!gs?.grid) return 0;
		const cs  = gs.config.cellSize;
		const cx  = Math.floor(worldX / cs);
		const cy  = Math.floor(worldY / cs);
		const gr  = Math.ceil(radius / cs);
		const x0  = Math.max(0, cx - gr);
		const x1  = Math.min(gs.gridWidth  - 1, cx + gr);
		const y0  = Math.max(0, cy - gr);
		const y1  = Math.min(gs.gridHeight - 1, cy + gr);
		let closestSq = Infinity;
		for (let gx = x0; gx <= x1; gx++) {
			for (let gy = y0; gy <= y1; gy++) {
				const t = gs.grid[gx]?.[gy]?.terrainType;
				if (t === 'shallow_water' || t === 'deep_water') {
					const dx = (gx - cx) * cs;
					const dy = (gy - cy) * cs;
					const dSq = dx * dx + dy * dy;
					if (dSq < closestSq) closestSq = dSq;
				}
			}
		}
		if (closestSq === Infinity) return 0;
		return Math.max(0, 1 - Math.sqrt(closestSq) / radius);
	}




	applyObjectTerrainModifiers() {
		if (!this.gridSystem) return;

		this.objects.forEach(obj => {
			if (!obj.type) return;
			const terrainType = this.tileMapLoader.terrainModifiers[obj.type.toUpperCase()];
			if (!terrainType) return;

			const cells = this.gridSystem.getObjectCellsForArea(obj.posX, obj.posY, obj.size.width, obj.size.height);
			for (const cell of cells) {
				if (!cell.originalTerrainType) cell.originalTerrainType = cell.terrainType;
				cell.terrainType = terrainType;
				cell.terrainModifier = obj;
			}

			obj.terrainType = terrainType;
		});
	}

	applyTerrainToGameMap(mapData) {
		// Apply terrain data to grid system if it exists
		if (this.gridSystem && this.gridSystem.pathfinder) {
			Utility.logDebug("[TileMapLoader] Applying terrain types to pathfinder");
	
			// Get terrain costs from the pathfinder or use our local copy
			let customTerrainCosts = {};
			
			// Start with our default costs
			Object.assign(customTerrainCosts, GridSystem.terrainCosts);
	
			// Check for custom terrain costs in map properties
			if (mapData.properties) {
				Object.keys(mapData.properties).forEach(key => {
					if (key.startsWith('terrain_cost_')) {
						const terrainType = key.replace('terrain_cost_', '');
						const cost = parseFloat(mapData.properties[key]);
						if (!isNaN(cost)) {
							customTerrainCosts[terrainType] = cost;
						}
					}
				});
			}
	
			// Process objects that modify terrain
			this.applyObjectTerrainModifiers();
			
            this.gridSystem.pathfinder.setTerrainCosts(customTerrainCosts);

            const pathfinderOptions = this.gridSystem.pathfinder.options;
            if (mapData.properties.pathfinderPreferPaths !== undefined) {
                pathfinderOptions.preferPaths = !!mapData.properties.pathfinderPreferPaths;
            }
            if (mapData.properties.pathfinderAvoidDifficultTerrain !== undefined) {
                pathfinderOptions.avoidDifficultTerrain = !!mapData.properties.pathfinderAvoidDifficultTerrain;
            }
            if (mapData.properties.pathfinderAllowDiagonals !== undefined) {
                pathfinderOptions.allowDiagonals = !!mapData.properties.pathfinderAllowDiagonals;
            }
            if (mapData.properties.pathfinderVisualizeSearch !== undefined) {
                pathfinderOptions.visualizeSearch = !!mapData.properties.pathfinderVisualizeSearch;
            }
            if (mapData.properties.pathfinderVisualizeRejectedNodes !== undefined) {
                pathfinderOptions.visualizeRejectedNodes = !!mapData.properties.pathfinderVisualizeRejectedNodes;
            }
            if (mapData.properties.pathfinderMaxVisualizedNodes !== undefined) {
                const maxNodes = Number(mapData.properties.pathfinderMaxVisualizedNodes);
                if (Number.isFinite(maxNodes) && maxNodes > 0) {
                    pathfinderOptions.maxVisualizedNodes = maxNodes;
                }
            }
            if (mapData.properties.pathfinderPathEdgePenaltyFactor !== undefined) {
                const edgePenalty = Number(mapData.properties.pathfinderPathEdgePenaltyFactor);
                if (Number.isFinite(edgePenalty)) {
                    pathfinderOptions.pathEdgePenaltyFactor = edgePenalty;
                }
            }
		}
	}



    // Keep the createDefaultMap method for initial loads
    createDefaultMap(mapId) {
        Utility.logDebug(`[GameMap] Creating default map for ${mapId}`);

        // Set basic properties
        this.name = mapId;
        this.id = mapId;
        this.description = 'Default Map';
        this.location = 'Unknown';

        // Set up dimensions
        this.dimensions = {
            width: 1000,
            height: 1000
        };

        // Set a background color
        if (this.layers.background) {
            // this.layers.background.style.backgroundColor = '#87CEEB';
        }

        // Add a spawn point
        this.spawnPoints.set('default', { x: 500, y: 500 });
        this.spawnPoints.set('myte', { x: 500, y: 500 });
        this.core?.toastManager?.warning?.(
            'Map failed to load - using empty fallback map',
            'Warning'
        );
    }

    setBackground(background) {
        if (!this.layers.background) return;

        this.backgroundReadyPromise = Promise.resolve();

        if (background.color) {
            // this.layers.background.style.backgroundColor = background.color;
        }

        if (background.url) {
            const bgUrl = background.url;
            this.layers.background.style.backgroundImage = `url(${background.url})`;
            this.layers.background.style.backgroundSize = 'cover';

            this.backgroundReadyPromise = new Promise(resolve => {
                const img = new Image();
                img.onload = () => resolve();
                img.onerror = () => resolve();
                img.src = bgUrl;

                if (typeof img.decode === 'function') {
                    img.decode().then(resolve).catch(() => resolve());
                }
            });
        }
    }

    _waitForAnimationFrame() {
        return new Promise(resolve => requestAnimationFrame(() => resolve()));
    }

    async waitForRevealReady() {
        await Promise.resolve(this.backgroundReadyPromise).catch(() => {});

        const camera = this.parent?.camera || null;

        await this._waitForAnimationFrame();

        if (camera) {
            camera.updateTransform(camera.posX, camera.posY, camera.zoomLevel);
        }

        if (this.gridSystem) {
            if (camera) {
                this.gridSystem.verifyActiveObjects(camera);
                this.gridSystem.updateCulling(camera);
            }

            for (const object of this.gridSystem.activeObjects || []) {
                if (object.update && !object.sleeping) {
                    object.update(0);
                }
            }

            this.renderer.flush(this.gridSystem.activeObjects || []);
        } else {
            for (const object of this.objects) {
                if (object.update) {
                    object.update(0);
                }
            }

            this.renderer.flush(this.objects);
        }

        await this._waitForAnimationFrame();
        await this._waitForAnimationFrame();
    }

    add(object, properties = {}) {
        if (!object) return null;

        // Apply any custom properties
        Object.assign(object, properties);
        if (typeof object.applyRuntimeProperties === 'function') {
            object.applyRuntimeProperties(properties);
        }

        if (!object.parent) {
            object.parent = this;
        }

        if (!object.map) {
            object.map = this;
        }

        if (!object.container) {
            object.container = this.parent;
        }

        if (object.id !== undefined && object.id !== null) {
            this.objectsById.set(String(object.id), object);
        }

        // Add to objects array
        this.objects.push(object);
        this.parent?.worldRegistry?.add(object, 'object');

        // Add to grid system
        if (this.gridSystem) {
            this.gridSystem.addObject(object);
        }

        // Render in the appropriate layer for this object type
        const renderLayer = this.getObjectRenderLayer(object);
        if (renderLayer) {
            object.render(renderLayer, this.parent);
        }

        return object;
    }

    addObject(typeOrObject, variant, x, y, options = {}) {
        if (typeOrObject && typeof typeOrObject === 'object' && variant === undefined) {
            return this.add(typeOrObject);
        }

        try {
            const object = MapObjectFactory.create(typeOrObject, variant, x, y, {
                ...options,
                parent: this
            });

            if (!object) {
                console.error(`Failed to create object of type: ${typeOrObject}, variant: ${variant}`);
                return null;
            }

            if (this.gridSystem) {
                try {
                    const newposition = this.gridSystem.snapToGrid(
                        x, y,
                        object.size.width,
                        object.size.height,
                        this.gridSystem.config.cellSize
                    );

                    object.posX = newposition.x;
                    object.posY = newposition.y;
                } catch (gridError) {
                    Utility.warnDebug(`[GameMap] Error snapping to grid:`, gridError);
                    object.posX = x;
                    object.posY = y;
                }
            }

            return this.add(object, options);
        } catch (error) {
            console.error(`[GameMap] Error in addObject:`, error);
            return null;
        }
    }

    addDroppedItem(type, variant, posX, posY) {
        const item = new DroppedMapItem(this, type, variant, posX, posY);
        if (this.layers.objects && item.element) {
            this.layers.objects.appendChild(item.element);
        }
        this.droppedItems.push(item);
        this.parent?.worldRegistry?.add(item, 'item');
        return item;
    }

    getObjectsInRadius(x, y, radius) {
        // OPTIMIZATION: Use grid system for spatial queries if available
        if (this.gridSystem) {
            const searchArea = {
                x: x - radius,
                y: y - radius,
                width: radius * 2,
                height: radius * 2
            };

            const nearbyObjects = this.gridSystem.getObjectsInArea(
                searchArea.x, searchArea.y,
                searchArea.width, searchArea.height
            );

            // Filter by actual radius (squared compare — no sqrt) and active state
            const radiusSq = radius * radius;
            return nearbyObjects.filter(obj => {
                const dx = obj.posX + obj.size.width / 2 - x;
                const dy = obj.posY + obj.size.height / 2 - y;
                return (dx * dx + dy * dy) <= radiusSq && obj.active;
            });
        }

        // Fallback to direct search if grid system is not available
        const radiusSq = radius * radius;
        return this.objects.filter(obj => {
            const dx = obj.posX + obj.size.width / 2 - x;
            const dy = obj.posY + obj.size.height / 2 - y;
            return (dx * dx + dy * dy) <= radiusSq && obj.active;
        });
    }

    getSpawnPoint(type = 'myte') {
        const spawn = this.spawnPoints.get(type);
        if (Array.isArray(spawn)) {
            // If it's an array of spawn points, choose random one
            return Utility.randomChoice(spawn);
        }
        return spawn || { x: 0, y: 0 };
    }

    getRandomPosition() {
        return {
            x: Math.random() * this.dimensions.width,
            y: Math.random() * this.dimensions.height
        };
    }

    isPositionValid(x, y) {
        // Check boundaries
        if (x < 0 || x > this.dimensions.width ||
            y < 0 || y > this.dimensions.height) {
            return false;
        }

        // OPTIMIZATION: Use grid system for collision check
        if (this.gridSystem) {
            const gridPos = this.gridSystem.worldToGrid(x, y);

            // Check if the grid cell is walkable
            if (gridPos.x >= 0 && gridPos.x < this.gridSystem.gridWidth &&
                gridPos.y >= 0 && gridPos.y < this.gridSystem.gridHeight) {
                return this.gridSystem.grid[gridPos.x][gridPos.y].walkable;
            }
        }

        // Fallback to object-based check
        const nearbyObjects = this.getObjectsInRadius(x, y, 50);
        return !nearbyObjects.some(obj => !obj.config.physics?.walkable);
    }

    removeInactiveObjects() {
        // Find all inactive objects
        const inactiveObjects = this.objects.filter(obj => !obj.active);

        // Remove each from the grid
        if (this.gridSystem) {
            inactiveObjects.forEach(obj => this.gridSystem.removeObject(obj));
        }

        inactiveObjects.forEach(obj => {
            if (obj.id !== undefined && obj.id !== null) {
                this.objectsById.delete(String(obj.id));
            }
            this.parent?.worldRegistry?.remove(obj);
        });

        // Remove from the main array
        this.objects = this.objects.filter(obj => obj.active);
    }

    tickUpdate(tickDelta) {
        for (const object of this.objects) {
            if (!object.tickUpdate) continue;
            // Skip sleeping objects that don't need off-screen simulation (e.g. static props).
            // Autonomous objects (butterflies, guards, balls) return true and always tick.
            if (object.sleeping && !object.shouldSimulateOffScreen?.()) continue;
            object.tickUpdate(tickDelta);
        }

        if (this.particleSystem) {
            this.particleSystem.tickUpdate(tickDelta);
        }
    }

    update(deltaTime) {
        if (this.gridSystem) {
            this.updateFrameSkip = (this.updateFrameSkip + 1) % 15;

            // Full consistency check several times per second so moving objects
            // can re-enter the viewport even if the camera is stationary.
            if (this.updateFrameSkip === 0) {
                this.gridSystem.verifyActiveObjects(this.parent.camera);
            }

            // Update culling (skips work when camera hasn't moved — see GridSystem)
            this.gridSystem.updateCulling(this.parent.camera);
            this.activeObjectsCount = this.gridSystem.activeObjects.size;

            // Animation / visual updates only — no DOM writes here
            for (const object of this.gridSystem.activeObjects) {
                if (object.update && !object.sleeping) {
                    object.update(deltaTime);
                }
            }

            this.parent?.attachments?.update?.();
            // Batch-flush all dirty renderStates to the DOM in one pass
            this.renderer.flush(this.gridSystem.activeObjects);
        } else {
            // Fallback when grid system isn't ready
            for (const object of this.objects) {
                if (object.update) object.update(deltaTime);
            }
            this.parent?.attachments?.update?.();
            this.renderer.flush(this.objects);
            this.activeObjectsCount = this.objects.length;
        }

        // Zone updates for active mytes.
        //
        // Zone effects stay per-frame on purpose: onMyteStay feeds
        // applyStatEffectsPerMs(effects, deltaTime), so throttling this to cell
        // crossings would silently stop per-ms stat accumulation. Room membership
        // below has no such constraint and IS cell-crossing gated — updateMembership
        // returns immediately when the entity has not changed cell.
        if (this.zoneManager) {
            this.mytes.forEach(myte => {
                if (myte.isActive) this.zoneManager.update(myte, deltaTime);
            });
        }

        if (this.regionManager) {
            this.mytes.forEach(myte => {
                if (myte.isActive) this.regionManager.updateMembership(myte, { layers: ['room'] });
            });
        }

        // Update dropped items (physics + magnet collection). Any deployed myte can
        // collect — not just the controlled one — so background mytes that walk over a
        // chest drop actually pick it up.
        if (this.droppedItems.length > 0) {
            const deployedMytes = this.mytes?.filter(m => m.isActive) || [];
            this.droppedItems = this.droppedItems.filter(item => {
                if (item.collected) {
                    item.remove();
                    this.parent?.worldRegistry?.remove(item);
                    return false;
                }
                item.update(deployedMytes, deltaTime);
                return true;
            });
        }

        // Periodic cleanup
        if (this.updateFrameSkip === 0) {
            this.removeInactiveObjects();
        }

        if (this.particleSystem) {
            this.particleSystem.update(deltaTime);
        }

        if (this.environmentManager) {
            this.environmentManager.update(deltaTime);
        }
    }

    dispose() {
        // Stop proximity polling and clear any proximity sounds before the new map takes over
        this._stopProximitySoundPolling();
        this.soundManager?.setProximitySounds(new Map());

        // Clean up dropped items (their DOM elements live in the shared layer)
        this.droppedItems.forEach(item => {
            item.remove();
            this.parent?.worldRegistry?.remove(item);
        });
        this.droppedItems = [];

        // Clean up objects
        this.objects.forEach(obj => {
            if (obj.remove) {
                obj.remove();
            }
            this.parent?.worldRegistry?.remove(obj);
        });
        this.objects = [];
        this.objectsById.clear();

        // Clean up zones
        // this.zones.clear();

        // Clean up spawn points
        this.spawnPoints.clear();

        // Clean up tile map loader
        if (this.tileMapLoader) {
            this.tileMapLoader.dispose();
            this.tileMapLoader = null;
        }

        // Clean up particle system
        if (this.particleSystem) {
            this.particleSystem.dispose();
            this.particleSystem = null;
        }

        if (this.environmentManager) {
            this.environmentManager.dispose();
            this.environmentManager = null;
        }

        // Clean up grid system
        if (this.gridSystem) {
            // Ensure grid system cleans up properly
            if (this.gridSystem.dispose) {
                this.gridSystem.dispose();
            }
            this.gridSystem = null;
        }

        if (this.layers && this.layers.debug) {
            // Clear all debug elements
            while (this.layers.debug.firstChild) {
                this.layers.debug.removeChild(this.layers.debug.firstChild);
            }
        }

        // dispose zones
        if (this.zoneManager) {
            this.zoneManager.dispose();
            this.zoneManager = null;
        }

        if (this.regionManager) {
            this.regionManager.clear();
            this.regionManager = null;
        }

        // Clear layer references
        this.layers = {};

        Utility.logDebug("[GameMap] Map disposed successfully");
    }
}
;
/* -- js/Map/GameZone.js -- */
// Zone types enum
const ZONE_TYPES = {
    REST: 'rest',
    PLAY: 'play',
    FOOD: 'food',
    SOCIAL: 'social',
    DANGER: 'danger',
    BOOST: 'boost'
};

// Add these constants at the top of your file
const ZONE_THRESHOLD = {
    TOUCHING: 'touching',  // Myte is just touching the zone (default)
    HALFWAY: 'halfway',    // Myte is at least halfway in the zone
    FULLY: 'fully'         // Myte is fully inside the zone
};

class Zone {
    static _definitions = new Map();

    static loadDefinitions(defsArray) {
        defsArray.forEach(def => Zone._definitions.set(def.id, def));
    }

    constructor(data, map) {
        this.map = map;
        this.id = data.id;
        this.type = String(data.type || '').toLowerCase();
        this.bounds = data.bounds;
        this.properties = {
            ...SiteConfig.zones.defaults,
            ...data.properties
        };
        this.displayName = data.properties?.displayName || this.type;

        // Geometry now lives in the shared region store; Zone keeps only the
        // behaviour (thresholds, buffs, stat effects). `this.bounds` is retained
        // as a read-only convenience for the many existing callers.
        this.region = map?.regionManager?.add(new SpatialRegion({
            id: this.id,
            layer: 'zone',
            shape: { kind: 'rect', bounds: this.bounds },
            properties: this.properties,
            source: this
        })) ?? null;

        // Track Mytes in the zone
        this.mytesInZone = new Set();

        // Visual element if zone is visible
        this.element = null;
        if (this.properties.visible) {
            this.createVisualElement();
        }
    }

    _getZoneDef() {
        return Zone._definitions.get(this.type) ?? null;
    }

    createVisualElement() {
        this.element = document.createElement('div');
        this.element.className = `zone ${this.type}-zone`;
        Object.assign(this.element.style, {
            position: 'absolute',
            left: `${this.bounds.x}px`,
            top: `${this.bounds.y}px`,
            width: `${this.bounds.width}px`,
            height: `${this.bounds.height}px`,
            pointerEvents: 'none'
        });

		// Add a new element with the type as the text and class name
		const newElement = document.createElement('span');
		newElement.className = "name";
		newElement.textContent = this.type;
		this.element.appendChild(newElement);


	}

    getTypeConfig() {
        return SiteConfig.zones.types[this.type] ?? {};
    }

    getCenterPoint() {
        if (this.region) return this.region.getCenterPoint();
        return {
            x: this.bounds.x + (this.bounds.width / 2),
            y: this.bounds.y + (this.bounds.height / 2)
        };
    }

    getBuffContextKey() {
        return `zone:${this.id ?? this.type}:${this.type}`;
    }

    getDefaultBuffId() {
        switch (this.type) {
            case ZONE_TYPES.REST: return 'zone_rest';
            case ZONE_TYPES.PLAY: return 'zone_play';
            case ZONE_TYPES.SOCIAL: return 'zone_social';
            case ZONE_TYPES.DANGER: return 'zone_danger';
            default: return null;
        }
    }

    getContextBuffDefinition() {
        if (this.properties.buffDefinition) {
            return this.properties.buffDefinition;
        }

        if (this.properties.buffId) {
            return this.properties.buffId;
        }

        const defaultBuffId = this.getDefaultBuffId();
        if (defaultBuffId) {
            return defaultBuffId;
        }

        if (this.type !== ZONE_TYPES.BOOST) {
            return null;
        }

        const strength = this.properties.strength ?? 1;
        const onApply = this.properties.effects ?? (
            this.properties.moodBoost != null
                ? { moodBoost: this.properties.moodBoost * strength }
                : {}
        );
        const stayConfig = this.getTypeConfig().stay ?? {};

        return {
            id: `boost_zone_${this.id ?? 'dynamic'}`,
            label: this.properties.buffLabel || 'Boost Zone',
            kind: 'buff',
            category: 'zone',
            priority: 16,
            durationMs: 0,
            cancellable: false,
            icon: this.properties.buffIcon || 'BZ',
            description: this.properties.buffDescription || 'This area is boosting your stats while you stay inside.',
            effects: {
                stats: {
                    moodPerMs: this.properties.moodPerMs ?? stayConfig.moodPerMs ?? 0,
                    boredomPerMs: this.properties.boredomPerMs ?? stayConfig.boredomPerMs ?? 0,
                    funPerMs: this.properties.funPerMs ?? stayConfig.funPerMs ?? 0,
                    comfortPerMs: this.properties.comfortPerMs ?? stayConfig.comfortPerMs ?? 0,
                    confidencePerMs: this.properties.confidencePerMs ?? stayConfig.confidencePerMs ?? 0
                }
            },
            onApply
        };
    }

    syncZoneBuff(myte, active = true) {
        myte.buffs?.syncContextBuff?.(
            this.getBuffContextKey(),
            this.getContextBuffDefinition(),
            {
                active,
                source: 'zone',
                payload: {
                    zoneId: this.id,
                    zoneType: this.type
                }
            }
        );
    }

    getDistanceToMyte(myte) {
        if (!myte) return Infinity;
        const center = this.getCenterPoint();
        const myteCenterX = myte.posX + ((myte.size?.width ?? 0) / 2);
        const myteCenterY = myte.posY + ((myte.size?.height ?? 0) / 2);
        return Math.hypot(center.x - myteCenterX, center.y - myteCenterY);
    }

    getTargetPointForMyte(myte) {
        const center = this.getCenterPoint();
        const targetX = center.x - ((myte?.size?.width ?? 0) / 2);
        const targetY = center.y - ((myte?.size?.height ?? 0) / 2);
        return this.map?.gridSystem?.findNearestValidPositionForEntity?.(myte, targetX, targetY, 10) ?? {
            x: targetX,
            y: targetY
        };
    }

    getIntersectionLevel(myteRect) {
        // Rect regions delegate straight back to RectUtils, so the thresholds
        // below see byte-identical ratios to the pre-region implementation.
        const ratio = this.region
            ? this.region.intersectionRatio(myteRect)
            : RectUtils.getIntersectionRatio(myteRect, this.bounds);
        if (ratio <= 0) return null;
        if (ratio >= 0.95) return ZONE_THRESHOLD.FULLY;
        if (ratio >= 0.5) return ZONE_THRESHOLD.HALFWAY;
        return ZONE_THRESHOLD.TOUCHING;
    }

    getMyteRect(myte) {
        return myte.getWorldRect();
    }

    containsMyte(myte) {
        return this.doesMeetThreshold(this.getIntersectionLevel(this.getMyteRect(myte)));
    }

    // Check if a Myte has entered or left the zone
    update(myte, deltaTime = 16) {
        const myteRect = this.getMyteRect(myte);
        const intersectionLevel = this.getIntersectionLevel(myteRect);
        
        // Check if the myte meets the threshold requirement for this zone
        const meetsThreshold = this.doesMeetThreshold(intersectionLevel);
        const wasInZone = this.mytesInZone.has(myte.id);
        
        if (meetsThreshold && !wasInZone) {
            // Myte just entered the zone and meets threshold
            this.onMyteEnter(myte);
            this.mytesInZone.add(myte.id);
            this.map?.regionManager?.setOccupant?.(this.region, myte, true);
        } else if (!meetsThreshold && wasInZone) {
            // Myte no longer meets threshold
            this.onMyteExit(myte);
            this.mytesInZone.delete(myte.id);
            this.map?.regionManager?.setOccupant?.(this.region, myte, false);
        } else if (meetsThreshold) {
            // Myte stays in zone and still meets threshold
            this.onMyteStay(myte, deltaTime);
        }
    }

    doesMeetThreshold(intersectionLevel) {
        if (intersectionLevel === null) {
            return false; // Not intersecting at all
        }
        
        switch (this.properties.threshold) {
            case ZONE_THRESHOLD.FULLY:
                return intersectionLevel === ZONE_THRESHOLD.FULLY;
                
            case ZONE_THRESHOLD.HALFWAY:
                return intersectionLevel === ZONE_THRESHOLD.HALFWAY || 
                       intersectionLevel === ZONE_THRESHOLD.FULLY;
                       
            case ZONE_THRESHOLD.TOUCHING:
            default:
                return true; // Any intersection is fine for TOUCHING threshold
        }
    }

    onMyteEnter(myte) {
        // Stat effects are applied passively each tick in onMyteStay
    }

    onMyteExit(myte) {
        // Pass
    }

    onMyteStay(myte, deltaTime) {
        const zoneDef = this._getZoneDef();
        if (!zoneDef?.effects) return;
        myte.stats?.applyStatEffectsPerMs?.(zoneDef.effects, deltaTime);
    }

}

// ZoneManager class to handle multiple zones
class ZoneManager {
    constructor(map) {
        this.parent = map;
        this.zones = new Map();

        if (!Zone._definitions.size) {
            fetch(Utility.preventCache('data/metadata/zones.json'))
                .then(r => r.json())
                .then(data => Zone.loadDefinitions(data.zones ?? []))
                .catch(err => console.error('[ZoneManager] Failed to load zone definitions:', err));
        }
    }

    addZone(zoneData) {
        const zone = new Zone(zoneData, this.parent);
        this.zones.set(zone.id, zone);
        
        if (zone.element) {
            this.parent.layers.background.appendChild(zone.element);
        }
        
        return zone;
    }

    removeZone(zoneId) {
        const zone = this.zones.get(zoneId);
        if (zone) {
            if (zone.element) {
                zone.element.remove();
            }
            this.zones.delete(zoneId);
        }
    }

    update(myte, deltaTime = 16) {
        this.zones.forEach(zone => {
            if (zone.properties.active) {
                zone.update(myte, deltaTime);
            }
        });
    }

    getActiveZonesForMyte(myte) {
        return Array.from(this.zones.values()).filter(zone =>
            zone?.properties?.active && zone.containsMyte(myte)
        );
    }

    getZonesOfType(type) {
        return Array.from(this.zones.values()).filter(zone => zone.type === type);
    }

    getNearbyZonesForMyte(myte, radius = Infinity) {
        return Array.from(this.zones.values())
            .filter(zone =>
                zone?.properties?.active &&
                zone.getDistanceToMyte(myte) <= radius
            )
            .sort((a, b) => a.getDistanceToMyte(myte) - b.getDistanceToMyte(myte));
    }

    dispose(){

        // loop through zones and remove elements
        this.zones.forEach(zone => {
            if (zone.element) {
                zone.element.remove();
            }
        });

        this.zones = new Map();


        
    }
}
;
/* -- js/Map/MapEnvironmentManager.js -- */
class MapEnvironmentManager {
    static EMPTY_PRESET_DATA = Object.freeze({
        schemaVersion: 1,
        presets: {}
    });

    static _presetPromise = null;
    static _presetData = null;

    static async loadPresetData(noCache = false) {
        if (noCache) {
            MapEnvironmentManager._presetData = null;
        }

        if (MapEnvironmentManager._presetData) {
            return MapEnvironmentManager._presetData;
        }

        if (MapEnvironmentManager._presetPromise) {
            return MapEnvironmentManager._presetPromise;
        }

        const url = noCache
            ? Utility.preventCache('data/metadata/environment-presets.json')
            : 'data/metadata/environment-presets.json';

        MapEnvironmentManager._presetPromise = fetch(url)
            .then(response => {
                if (!response.ok) {
                    throw new Error(`Environment presets request failed: ${response.status}`);
                }
                return response.json();
            })
            .then(data => {
                MapEnvironmentManager._presetData = (data && typeof data === 'object')
                    ? data
                    : Utility.deepClone(MapEnvironmentManager.EMPTY_PRESET_DATA);
                return MapEnvironmentManager._presetData;
            })
            .catch(error => {
                console.warn('[MapEnvironmentManager] Failed to load environment presets JSON:', error);
                MapEnvironmentManager._presetData = Utility.deepClone(MapEnvironmentManager.EMPTY_PRESET_DATA);
                return MapEnvironmentManager._presetData;
            })
            .finally(() => {
                MapEnvironmentManager._presetPromise = null;
            });

        return MapEnvironmentManager._presetPromise;
    }

    static parseColor(color, fallback = [0, 0, 0, 0]) {
        if (Array.isArray(color)) {
            const [r, g, b, a = 1] = color;
            return [
                Utility.clamp(Number(r) || 0, 0, 255),
                Utility.clamp(Number(g) || 0, 0, 255),
                Utility.clamp(Number(b) || 0, 0, 255),
                Utility.clamp(Number(a), 0, 1)
            ];
        }

        const value = String(color || '').trim();
        if (!value) {
            return [...fallback];
        }

        const rgbaMatch = value.match(/^rgba?\(([^)]+)\)$/i);
        if (rgbaMatch) {
            const parts = rgbaMatch[1].split(',').map(part => part.trim());
            const r = Utility.clamp(Number(parts[0]) || 0, 0, 255);
            const g = Utility.clamp(Number(parts[1]) || 0, 0, 255);
            const b = Utility.clamp(Number(parts[2]) || 0, 0, 255);
            const a = parts[3] != null ? Utility.clamp(Number(parts[3]), 0, 1) : 1;
            return [r, g, b, a];
        }

        const hex = value.replace('#', '');
        if (hex.length === 6 || hex.length === 8) {
            const hasAlpha = hex.length === 8;
            const offset = hasAlpha ? 2 : 0;
            const alpha = hasAlpha ? parseInt(hex.slice(0, 2), 16) / 255 : 1;
            const r = parseInt(hex.slice(offset + 0, offset + 2), 16);
            const g = parseInt(hex.slice(offset + 2, offset + 4), 16);
            const b = parseInt(hex.slice(offset + 4, offset + 6), 16);
            return [r, g, b, Utility.clamp(alpha, 0, 1)];
        }

        return [...fallback];
    }

    static toRgbaString(color) {
        const [r, g, b, a = 1] = MapEnvironmentManager.parseColor(color);
        return `rgba(${Math.round(r)}, ${Math.round(g)}, ${Math.round(b)}, ${Utility.clamp(a, 0, 1)})`;
    }

    static scaleColorAlpha(color, alphaMultiplier = 1) {
        const rgba = MapEnvironmentManager.parseColor(color);
        rgba[3] = Utility.clamp(rgba[3] * alphaMultiplier, 0, 1);
        return rgba;
    }

    constructor(gameMap) {
        this.gameMap = gameMap;
        this.container = gameMap?.parent || null;
        this.canvas = this.container?.canvas || null;
        this.timeManager = this.container?.timeManager || GameTime.instance || null;
        this.mapData = null;
        this.presetData = null;
        this.config = null;

        this.frontLayer = null;
        this.backLayer = null;
        this.frontRoot = null;
        this.backRoot = null;
        this.fillElement = null;
        this.gradientElement = null;
        this.vignetteElement = null;

        this.lightingOverlay = null;
        this.lightingColorCanvas = null;
        this.lightingDarknessCanvas = null;
        this.lightingColorContext = null;
        this.lightingDarknessContext = null;
        this._lightingCanvasScale = 1;
        this._lightingBounds = null;

        this.roomVolumes = [];
        this.lightOpenings = [];

        this.currentAtmosphere = null;
        this.targetAtmosphere = null;
        this.atmosphereFrom = null;
        this.atmosphereTransitionMs = 0;
        this.atmosphereTransitionElapsed = 0;
        this.atmosphereTransitionActive = false;
        this._atmosphereSignature = '';
        this._lightingSignature = '';

        this._timeData = this.getTimeData();
        this._subscriptions = [];
        this._isInitialized = false;

        this._boundResize = () => {
            this.syncLightingOverlayBounds(true);
            this.resizeLightingCanvases(null, true);
            this._lightingSignature = '';
            this.renderLighting(true);
        };
    }

    async initialize(mapData = {}) {
        this.mapData = mapData || {};
        this.presetData = await MapEnvironmentManager.loadPresetData(this.gameMap?.noCache === true);
        this.ensureEnvironmentLayers();
        this.ensureLightingOverlay();
        this.config = this.resolveConfig();
        this.roomVolumes = this.buildRoomVolumes();
        this.lightOpenings = this.buildLightOpenings();
        this.registerRoomRegions();
        this._timeData = this.getTimeData();
        this.currentAtmosphere = this.resolveAtmosphereState(this._timeData);
        this.targetAtmosphere = Utility.deepClone(this.currentAtmosphere);
        this.atmosphereFrom = Utility.deepClone(this.currentAtmosphere);
        this.subscribeToTime();
        window.addEventListener('resize', this._boundResize);
        this.syncLightingOverlayBounds(true);
        this.resizeLightingCanvases(null, true);
        this.renderAtmosphere(true);
        this.renderLighting(true);
        this._isInitialized = true;
    }

    ensureEnvironmentLayers() {
        const canvas = this.canvas;
        if (!canvas) {
            return;
        }

        this.backLayer = canvas.querySelector('.layer.environment-back');
        this.frontLayer = canvas.querySelector('.layer.environment-front');

        if (!this.backLayer) {
            this.backLayer = document.createElement('div');
            this.backLayer.className = 'layer environment-back';
            canvas.appendChild(this.backLayer);
        }

        if (!this.frontLayer) {
            this.frontLayer = document.createElement('div');
            this.frontLayer.className = 'layer environment-front';
            canvas.appendChild(this.frontLayer);
        }

        this.backLayer.querySelectorAll('.map-environment-root').forEach(node => node.remove());
        this.frontLayer.querySelectorAll('.map-environment-root').forEach(node => node.remove());

        this.backRoot = document.createElement('div');
        this.backRoot.className = 'map-environment-root map-environment-root--back';
        this.backLayer.appendChild(this.backRoot);

        this.frontRoot = document.createElement('div');
        this.frontRoot.className = 'map-environment-root map-environment-root--front';
        this.frontLayer.appendChild(this.frontRoot);

        this.fillElement = document.createElement('div');
        this.fillElement.className = 'map-environment-fill';
        this.frontRoot.appendChild(this.fillElement);

        this.gradientElement = document.createElement('div');
        this.gradientElement.className = 'map-environment-gradient';
        this.frontRoot.appendChild(this.gradientElement);

        this.vignetteElement = document.createElement('div');
        this.vignetteElement.className = 'map-environment-vignette';
        this.frontRoot.appendChild(this.vignetteElement);
    }

    ensureLightingOverlay() {
        const root = this.container?.element || null;
        if (!root) {
            return;
        }

        root.querySelectorAll('.lighting-overlay').forEach(node => node.remove());

        this.lightingOverlay = document.createElement('div');
        this.lightingOverlay.className = 'lighting-overlay ignore';
        root.appendChild(this.lightingOverlay);

        this.lightingDarknessCanvas = document.createElement('canvas');
        this.lightingDarknessCanvas.className = 'lighting-overlay__canvas lighting-overlay__darkness';
        this.lightingOverlay.appendChild(this.lightingDarknessCanvas);

        this.lightingColorCanvas = document.createElement('canvas');
        this.lightingColorCanvas.className = 'lighting-overlay__canvas lighting-overlay__color';
        this.lightingOverlay.appendChild(this.lightingColorCanvas);

        this.lightingColorContext = this.lightingColorCanvas.getContext('2d');
        this.lightingDarknessContext = this.lightingDarknessCanvas.getContext('2d');
    }

    getElementRect(element) {
        if (!element) {
            return {
                left: 0,
                top: 0,
                width: 0,
                height: 0,
                right: 0,
                bottom: 0
            };
        }

        if (typeof this.container?.getRect === 'function') {
            return this.container.getRect(element);
        }

        const rect = element.getBoundingClientRect();
        const left = rect.left + window.scrollX;
        const top = rect.top + window.scrollY;
        return {
            left,
            top,
            width: rect.width,
            height: rect.height,
            right: left + rect.width,
            bottom: top + rect.height
        };
    }

    getViewportBounds() {
        const root = this.container?.element || null;
        // Container geometry is cached by ContainerManager (invalidated on resize/
        // fullscreen); only the canvas rect must be measured live because the
        // camera CSS transform moves it every frame.
        const containerRect = typeof this.container?.getContainerRect === 'function'
            ? this.container.getContainerRect()
            : this.getElementRect(root);
        const canvasRect = this.getElementRect(this.canvas);
        const contentLeft = containerRect.left + Number(root?.clientLeft || 0);
        const contentTop = containerRect.top + Number(root?.clientTop || 0);
        const contentWidth = Math.max(0, Number(root?.clientWidth) || 0);
        const contentHeight = Math.max(0, Number(root?.clientHeight) || 0);
        const contentRight = contentLeft + contentWidth;
        const contentBottom = contentTop + contentHeight;
        const canvasLeft = Number.isFinite(canvasRect.left) ? canvasRect.left : contentLeft;
        const canvasTop = Number.isFinite(canvasRect.top) ? canvasRect.top : contentTop;
        const canvasRight = Number.isFinite(canvasRect.right) ? canvasRect.right : (canvasLeft + (canvasRect.width || 0));
        const canvasBottom = Number.isFinite(canvasRect.bottom) ? canvasRect.bottom : (canvasTop + (canvasRect.height || 0));
        const left = Math.max(contentLeft, canvasLeft);
        const top = Math.max(contentTop, canvasTop);
        const right = Math.min(contentRight, canvasRight);
        const bottom = Math.min(contentBottom, canvasBottom);
        const width = Math.max(0, right - left);
        const height = Math.max(0, bottom - top);
        const offsetLeft = Math.max(0, left - contentLeft);
        const offsetTop = Math.max(0, top - contentTop);

        return {
            left,
            top,
            right,
            bottom,
            width,
            height,
            offsetLeft,
            offsetTop,
            containerRect,
            canvasRect
        };
    }

    syncLightingOverlayBounds(force = false) {
        if (!this.lightingOverlay) {
            return null;
        }

        const bounds = this.getViewportBounds();
        const rounded = {
            left: Math.round(bounds.offsetLeft),
            top: Math.round(bounds.offsetTop),
            width: Math.round(bounds.width),
            height: Math.round(bounds.height)
        };
        const previous = this._lightingBounds;
        const changed = force ||
            !previous ||
            previous.left !== rounded.left ||
            previous.top !== rounded.top ||
            previous.width !== rounded.width ||
            previous.height !== rounded.height;

        if (changed) {
            this.lightingOverlay.style.left = `${rounded.left}px`;
            this.lightingOverlay.style.top = `${rounded.top}px`;
            this.lightingOverlay.style.width = `${rounded.width}px`;
            this.lightingOverlay.style.height = `${rounded.height}px`;
            this._lightingBounds = rounded;
        }

        return {
            ...bounds,
            offsetLeft: rounded.left,
            offsetTop: rounded.top,
            width: rounded.width,
            height: rounded.height
        };
    }

    subscribeToTime() {
        if (!this.timeManager?.subscribe) {
            return;
        }

        const events = ['minute', 'dayNight', 'light', 'moonPhase', 'season'];
        events.forEach(eventName => {
            const callback = timeData => {
                this._timeData = timeData || this.getTimeData();
                this.recomputeAtmosphereTarget();
            };
            this.timeManager.subscribe(eventName, callback);
            this._subscriptions.push({ eventName, callback });
        });
    }

    getTimeData() {
        return this.timeManager?.getTimeData?.() || {
            minute: 0,
            hour: 12,
            lightLevel: 1,
            timeOfDay: 'midday',
            moonPhase: 'full',
            season: 'spring',
            dayProgress: 0.5,
            totalElapsedSeconds: 0
        };
    }

    resolveConfig() {
        const mapProps = this.mapData?.properties || {};
        const location = String(this.mapData?.environment?.location || '').toLowerCase();
        const fallbackPresetId = (location === 'interior' || location === 'inside' || location === 'house')
            ? 'indoors-soft'
            : 'outside-default';
        const presetId = String(
            mapProps.environmentPreset ||
            mapProps.environmentProfile ||
            fallbackPresetId
        ).trim();
        const presets = this.presetData?.presets || {};
        const basePreset =
            presets[presetId] ||
            presets[fallbackPresetId] ||
            Object.values(presets)[0] ||
            {};
        const inlineOverrides = mapProps.environmentOverrides && typeof mapProps.environmentOverrides === 'object'
            ? mapProps.environmentOverrides
            : {};

        return Utility.deepMerge(
            Utility.deepClone(basePreset),
            inlineOverrides
        );
    }

    buildRoomVolumes() {
        const authoredRooms = Array.isArray(this.mapData?.environment?.rooms)
            ? this.mapData.environment.rooms
            : [];
        const roomDefaults = this.getRoomDefaults();

        if (authoredRooms.length > 0) {
            return authoredRooms.map(room => this.normalizeRoomVolume(room, roomDefaults)).filter(Boolean);
        }

        const location = String(this.mapData?.environment?.location || '').toLowerCase();
        if (location !== 'interior' && location !== 'inside' && location !== 'house') {
            return [];
        }

        const zones = Array.from(this.gameMap?.zoneManager?.zones?.values?.() || []);
        const roomLikeZones = zones.filter(zone => ['rest', 'play', 'food', 'social'].includes(zone?.type));
        return roomLikeZones.map(zone => this.normalizeRoomVolume({
            id: zone.id,
            displayName: zone.displayName,
            bounds: zone.bounds,
            properties: zone.properties
        }, roomDefaults)).filter(Boolean);
    }

    normalizeRoomVolume(source, defaults = {}) {
        const bounds = source?.bounds || null;
        if (!bounds || !Number.isFinite(bounds.width) || !Number.isFinite(bounds.height) || bounds.width <= 0 || bounds.height <= 0) {
            return null;
        }

        const props = source?.properties || {};
        return {
            id: String(source.id || source.displayName || `room_${Math.round(bounds.x)}_${Math.round(bounds.y)}`)
                .toLowerCase()
                .replace(/[^a-z0-9_-]+/g, '_'),
            displayName: source.displayName || props.displayName || source.id || 'Room',
            bounds: {
                x: Number(bounds.x) || 0,
                y: Number(bounds.y) || 0,
                width: Number(bounds.width) || 0,
                height: Number(bounds.height) || 0
            },
            lighting: {
                ambientFloor: Number(props.ambientFloor ?? props.roomAmbientFloor ?? defaults.ambientFloor ?? 0.18),
                ambientCeiling: Number(props.ambientCeiling ?? props.roomAmbientCeiling ?? defaults.ambientCeiling ?? 0.72),
                fillColor: props.fillColor || defaults.fillColor || 'rgba(255, 221, 172, 0.26)',
                shadowColor: props.shadowColor || this.config?.lighting?.darknessColor || 'rgba(18, 18, 28, 1)',
                feather: Number(props.feather ?? props.roomFeather ?? defaults.feather ?? 36),
                mode: String(props.lightingMode || props.roomLightingMode || defaults.mode || 'mixed').toLowerCase()
            }
        };
    }

    /**
     * Publish the lighting rooms into the shared region store as layer `room`.
     *
     * Lighting keeps its own `roomVolumes` and all of its maths — this does not
     * change how anything renders. The point is that room geometry stops being
     * private to the lighting system, so indoor/outdoor checks, occupancy queries
     * and the future wall/enclosure work have somewhere real to read it from
     * instead of inventing a fourth representation.
     *
     * Regions keep the authored polygon where one exists (Tiled stores polygon
     * points relative to the object origin, so they are offset back to world
     * space here); the lighting normaliser discards it and uses bounds only.
     */
    registerRoomRegions() {
        const regionManager = this.gameMap?.regionManager;
        if (!regionManager) return;

        for (const existing of regionManager.all('room')) {
            regionManager.remove(existing);
        }

        const authored = Array.isArray(this.mapData?.environment?.rooms)
            ? this.mapData.environment.rooms
            : [];
        const polygonById = new Map();
        for (const room of authored) {
            if (!Array.isArray(room?.polygon) || room.polygon.length < 3) continue;
            const originX = Number(room.bounds?.x) || 0;
            const originY = Number(room.bounds?.y) || 0;
            polygonById.set(
                String(room.id).toLowerCase(),
                room.polygon.map(p => ({ x: originX + (Number(p.x) || 0), y: originY + (Number(p.y) || 0) }))
            );
        }

        for (const volume of this.roomVolumes) {
            const polygon = polygonById.get(String(volume.id).toLowerCase());
            regionManager.add(new SpatialRegion({
                id: volume.id,
                layer: 'room',
                shape: polygon
                    ? { kind: 'polygon', points: polygon, bounds: volume.bounds }
                    : { kind: 'rect', bounds: volume.bounds },
                properties: {
                    displayName: volume.displayName,
                    indoor: true,
                    lighting: volume.lighting
                },
                source: volume
            }));
        }
    }

    buildLightOpenings() {
        const authoredOpenings = Array.isArray(this.mapData?.environment?.lightOpenings)
            ? this.mapData.environment.lightOpenings
            : [];

        return authoredOpenings
            .map(opening => {
                const bounds = opening?.bounds || null;
                if (!bounds) {
                    return null;
                }

                const props = opening.properties || {};
                return {
                    id: String(opening.id || `opening_${Math.round(bounds.x)}_${Math.round(bounds.y)}`)
                        .toLowerCase()
                        .replace(/[^a-z0-9_-]+/g, '_'),
                    roomA: String(props.roomA || props.from || '').toLowerCase(),
                    roomB: String(props.roomB || props.to || '').toLowerCase(),
                    spillFactor: Utility.clamp(Number(props.spillFactor ?? props.spill ?? 0.16), 0, 1),
                    bounds: {
                        x: Number(bounds.x) || 0,
                        y: Number(bounds.y) || 0,
                        width: Number(bounds.width) || 0,
                        height: Number(bounds.height) || 0
                    }
                };
            })
            .filter(Boolean);
    }

    getRoomDefaults() {
        return this.config?.lighting?.roomDefaults || {};
    }

    isAtmosphereOverlayEnabled() {
        return this.gameMap?.getTimeOfDayOverlayEnabledSetting?.() !== false;
    }

    refreshDisplaySettings() {
        this._atmosphereSignature = '';
        this.renderAtmosphere(true);
    }

    recomputeAtmosphereTarget(immediate = false) {
        const nextState = this.resolveAtmosphereState(this._timeData);
        const transitionMs = Math.max(0, Number(nextState.transitionMs || this.config?.atmosphere?.defaultTransitionMs || 0));

        if (immediate || !this.currentAtmosphere) {
            this.currentAtmosphere = Utility.deepClone(nextState);
            this.targetAtmosphere = Utility.deepClone(nextState);
            this.atmosphereFrom = Utility.deepClone(nextState);
            this.atmosphereTransitionMs = 0;
            this.atmosphereTransitionElapsed = 0;
            this.atmosphereTransitionActive = false;
            this.renderAtmosphere(true);
            this.renderLighting(true);
            return;
        }

        this.atmosphereFrom = Utility.deepClone(this.currentAtmosphere);
        this.targetAtmosphere = Utility.deepClone(nextState);
        this.atmosphereTransitionMs = transitionMs;
        this.atmosphereTransitionElapsed = 0;
        this.atmosphereTransitionActive = transitionMs > 0;

        if (!this.atmosphereTransitionActive) {
            this.currentAtmosphere = Utility.deepClone(nextState);
            this.renderAtmosphere(true);
            this.renderLighting(true);
        }
    }

    resolveAtmosphereState(timeData = {}) {
        const atmosphere = this.config?.atmosphere || {};
        const cycleState = this.resolveSunCycleState(timeData, atmosphere);
        const defaultGradientStops = [
            { position: 0.0, color: 'rgba(0, 0, 0, 0)' },
            { position: 0.25, color: 'rgba(0, 0, 0, 0)' },
            { position: 0.5, color: 'rgba(0, 0, 0, 0)' },
            { position: 0.75, color: 'rgba(0, 0, 0, 0)' },
            { position: 1.0, color: 'rgba(0, 0, 0, 0)' }
        ];

        const bandConfig = cycleState.bandConfig || {};
        const bandStops = (Array.isArray(bandConfig.stops) && bandConfig.stops.length > 0
            ? bandConfig.stops
            : defaultGradientStops
        ).map(stop => ({
            position: Utility.clamp(Number(stop.position ?? 0), 0, 1),
            color: MapEnvironmentManager.parseColor(stop.color || 'rgba(0, 0, 0, 0)')
        }));

        const nightOpacity = Utility.clamp(
            (cycleState.mode === 'night' ? cycleState.nightStrength : 0) * Number(atmosphere.nightOpacityMax ?? 0.76) * 0.18,
            0,
            1
        );
        const nightColor = MapEnvironmentManager.scaleColorAlpha(
            atmosphere.nightColor || 'rgba(14, 34, 84, 1)',
            nightOpacity
        );

        const vignetteOpacity = Utility.clamp(
            (cycleState.mode === 'night' ? cycleState.nightStrength : 0) * Number(atmosphere.vignetteOpacityMax ?? 0.12) * 0.35,
            0,
            1
        );
        const vignetteColor = MapEnvironmentManager.scaleColorAlpha(
            atmosphere.vignetteColor || 'rgba(6, 12, 28, 1)',
            vignetteOpacity
        );

        return {
            transitionMs: Number(atmosphere.transitionMs ?? atmosphere.defaultTransitionMs ?? 0),
            globalBlendMode: atmosphere.nightBlendMode || 'multiply',
            globalColor: nightColor,
            gradientEnabled: cycleState.bandStrength > 0.001 && bandStops.length > 0,
            gradientBlendMode: bandConfig.blendMode || 'screen',
            gradientOpacity: Utility.clamp(
                Number(bandConfig.bandOpacity ?? 0.9) * cycleState.bandStrength,
                0,
                1
            ),
            gradientAngle: Number(bandConfig.angle ?? (cycleState.mode === 'sunrise' ? -100 : 100)),
            gradientOriginX: Utility.lerp(
                Number(bandConfig.startX ?? 0.5),
                Number(bandConfig.endX ?? 0.5),
                cycleState.positionProgress
            ),
            gradientOriginY: Utility.lerp(
                Number(bandConfig.startY ?? bandConfig.originY ?? 0.5),
                Number(bandConfig.endY ?? bandConfig.originY ?? 0.5),
                cycleState.positionProgress
            ),
            gradientSpan: Utility.lerp(
                Math.max(0.5, Number(bandConfig.startSpan ?? bandConfig.span ?? 1.3)),
                Math.max(0.5, Number(bandConfig.endSpan ?? bandConfig.span ?? 1.3)),
                cycleState.positionProgress
            ),
            gradientStops: bandStops,
            vignetteColor,
            vignetteOpacity
        };
    }

    resolveLightingPeriodState(timeData = {}) {
        const lighting = this.config?.lighting || {};
        const atmosphere = this.config?.atmosphere || {};
        const cycleState = this.resolveSunCycleState(timeData, atmosphere);

        return {
            darknessFactor: Utility.clamp(cycleState.nightStrength, 0, 1),
            darknessOpacityMax: Utility.clamp(
                Number(lighting.darknessOpacityMax ?? 0.82),
                0,
                1
            ),
            darknessColor: lighting.darknessColor || atmosphere.nightColor || 'rgba(12, 30, 74, 1)',
            cycleMode: cycleState.mode,
            positionProgress: cycleState.positionProgress || 0,
            bandStrength: cycleState.bandStrength || 0,
            bandConfig: cycleState.bandConfig || null
        };
    }

    resolveSunCycleState(timeData = {}, atmosphere = {}) {
        const currentMinutes = this.getMinutesFromTimeData(timeData);
        const sunriseStart = this.parseTimeToMinutes(atmosphere?.sunrise?.start);
        const sunriseEnd = this.parseTimeToMinutes(atmosphere?.sunrise?.end);
        const sunsetStart = this.parseTimeToMinutes(atmosphere?.sunset?.start);
        const sunsetEnd = this.parseTimeToMinutes(atmosphere?.sunset?.end);

        if (this.isValidRange(sunsetStart, sunsetEnd) && this.isMinutesInRange(currentMinutes, sunsetStart, sunsetEnd)) {
            const progress = this.getRangeProgress(currentMinutes, sunsetStart, sunsetEnd);
            const positionProgress = this.easeInOutSine(progress);
            const nightStrength = this.easeInOutSine(progress);
            const bandStrength = Math.pow(Math.sin(progress * Math.PI), 0.72);
            return {
                mode: 'sunset',
                positionProgress,
                bandStrength,
                nightStrength,
                bandConfig: atmosphere.sunset || {}
            };
        }

        if (this.isValidRange(sunriseStart, sunriseEnd) && this.isMinutesInRange(currentMinutes, sunriseStart, sunriseEnd)) {
            const progress = this.getRangeProgress(currentMinutes, sunriseStart, sunriseEnd);
            const positionProgress = this.easeInOutSine(progress);
            const nightStrength = 1 - this.easeInOutSine(progress);
            const bandStrength = Math.pow(Math.sin(progress * Math.PI), 0.72);
            return {
                mode: 'sunrise',
                positionProgress,
                bandStrength,
                nightStrength,
                bandConfig: atmosphere.sunrise || {}
            };
        }

        const isNightAfterSunset = Number.isFinite(sunsetEnd) && currentMinutes >= sunsetEnd;
        const isNightBeforeSunrise = Number.isFinite(sunriseStart) && currentMinutes < sunriseStart;
        if (isNightAfterSunset || isNightBeforeSunrise) {
            return {
                mode: 'night',
                positionProgress: 1,
                bandStrength: 0,
                nightStrength: 1,
                bandConfig: null
            };
        }

        return {
            mode: 'day',
            positionProgress: 0,
            bandStrength: 0,
            nightStrength: 0,
            bandConfig: null
        };
    }

    isValidRange(startMinutes, endMinutes) {
        return Number.isFinite(startMinutes) && Number.isFinite(endMinutes) && startMinutes !== endMinutes;
    }

    isMinutesInRange(currentMinutes, startMinutes, endMinutes) {
        if (!this.isValidRange(startMinutes, endMinutes)) {
            return false;
        }

        if (startMinutes < endMinutes) {
            return currentMinutes >= startMinutes && currentMinutes < endMinutes;
        }

        return currentMinutes >= startMinutes || currentMinutes < endMinutes;
    }

    getRangeProgress(currentMinutes, startMinutes, endMinutes) {
        if (!this.isValidRange(startMinutes, endMinutes)) {
            return 0;
        }

        const span = this.getWrappedMinuteDistance(startMinutes, endMinutes);
        const traveled = this.getWrappedMinuteDistance(startMinutes, currentMinutes);
        return span > 0 ? Utility.clamp(traveled / span, 0, 1) : 0;
    }

    easeOutQuad(t = 0) {
        const clamped = Utility.clamp(t, 0, 1);
        return 1 - ((1 - clamped) * (1 - clamped));
    }

    easeInOutSine(t = 0) {
        const clamped = Utility.clamp(t, 0, 1);
        return -(Math.cos(Math.PI * clamped) - 1) / 2;
    }

    parseTimeToMinutes(value) {
        if (typeof value !== 'string') {
            return null;
        }

        const match = value.trim().match(/^(\d{1,2}):(\d{2})$/);
        if (!match) {
            return null;
        }

        const hours = Number(match[1]);
        const minutes = Number(match[2]);
        if (!Number.isFinite(hours) || !Number.isFinite(minutes)) {
            return null;
        }

        return ((hours * 60) + minutes + 1440) % 1440;
    }

    getMinutesFromTimeData(timeData = {}) {
        const totalElapsedSeconds = Number(timeData.totalElapsedSeconds);
        const dayDurationInMinutes = Number(this.timeManager?.config?.dayDurationInMinutes);
        if (Number.isFinite(totalElapsedSeconds) && Number.isFinite(dayDurationInMinutes) && dayDurationInMinutes > 0) {
            const gameMinutes = totalElapsedSeconds * (24 / dayDurationInMinutes);
            return ((gameMinutes % 1440) + 1440) % 1440;
        }

        const hour = Number(timeData.hour ?? 0);
        const minute = Number(timeData.minute ?? 0);
        return (((hour * 60) + minute) + 1440) % 1440;
    }

    getWrappedMinuteDistance(fromMinutes, toMinutes) {
        return ((toMinutes - fromMinutes) + 1440) % 1440;
    }

    interpolateAtmosphereState(fromState, toState, t) {
        const lerpColor = (fromColor, toColor) => ([
            Utility.lerp(fromColor[0], toColor[0], t),
            Utility.lerp(fromColor[1], toColor[1], t),
            Utility.lerp(fromColor[2], toColor[2], t),
            Utility.lerp(fromColor[3], toColor[3], t)
        ]);

        const stops = [];
        const fromStops = Array.isArray(fromState.gradientStops) ? fromState.gradientStops : [];
        const toStops = Array.isArray(toState.gradientStops) ? toState.gradientStops : [];
        const stopCount = Math.min(fromStops.length, toStops.length);
        for (let index = 0; index < stopCount; index++) {
            stops.push({
                position: Utility.lerp(fromStops[index].position, toStops[index].position, t),
                color: lerpColor(fromStops[index].color, toStops[index].color)
            });
        }

        return {
            transitionMs: toState.transitionMs,
            globalBlendMode: t < 0.5 ? fromState.globalBlendMode : toState.globalBlendMode,
            globalColor: lerpColor(fromState.globalColor, toState.globalColor),
            gradientEnabled: t < 0.5 ? fromState.gradientEnabled : toState.gradientEnabled,
            gradientBlendMode: t < 0.5 ? fromState.gradientBlendMode : toState.gradientBlendMode,
            gradientOpacity: Utility.lerp(fromState.gradientOpacity, toState.gradientOpacity, t),
            gradientAngle: Utility.lerp(fromState.gradientAngle, toState.gradientAngle, t),
            gradientOriginX: Utility.lerp(fromState.gradientOriginX, toState.gradientOriginX, t),
            gradientOriginY: Utility.lerp(fromState.gradientOriginY, toState.gradientOriginY, t),
            gradientSpan: Utility.lerp(fromState.gradientSpan, toState.gradientSpan, t),
            gradientStops: stops.length > 0 ? stops : Utility.deepClone(toState.gradientStops),
            vignetteColor: lerpColor(fromState.vignetteColor, toState.vignetteColor),
            vignetteOpacity: Utility.lerp(fromState.vignetteOpacity, toState.vignetteOpacity, t)
        };
    }

    update(deltaTime = 16) {
        if (!this._isInitialized) {
            return;
        }

        if (this.atmosphereTransitionActive && this.targetAtmosphere && this.atmosphereFrom) {
            this.atmosphereTransitionElapsed += deltaTime;
            const progress = this.atmosphereTransitionMs > 0
                ? Utility.clamp(this.atmosphereTransitionElapsed / this.atmosphereTransitionMs, 0, 1)
                : 1;
            // Interpolated state differs every frame — force, skipping the signature build
            this.currentAtmosphere = this.interpolateAtmosphereState(this.atmosphereFrom, this.targetAtmosphere, progress);
            this.renderAtmosphere(true);
            if (progress >= 1) {
                this.currentAtmosphere = Utility.deepClone(this.targetAtmosphere);
                this.atmosphereTransitionActive = false;
            }
        }

        this.renderLighting(false);
    }

    buildGradientCss(state) {
        if (!state.gradientEnabled || state.gradientOpacity <= 0 || !Array.isArray(state.gradientStops) || state.gradientStops.length === 0) {
            return 'none';
        }

        const stops = state.gradientStops.map(stop => {
            const color = [...stop.color];
            color[3] = Utility.clamp(color[3] * state.gradientOpacity, 0, 1);
            return `${MapEnvironmentManager.toRgbaString(color)} ${Math.round(Utility.clamp(stop.position, 0, 1) * 100)}%`;
        });

        return `linear-gradient(${state.gradientAngle}deg, ${stops.join(', ')})`;
    }

    buildVignetteCss(state) {
        const color = [...state.vignetteColor];
        color[3] = Utility.clamp(state.vignetteOpacity, 0, 1);
        const outerColor = MapEnvironmentManager.toRgbaString(color);
        return `radial-gradient(circle at 50% 50%, rgba(0, 0, 0, 0) 42%, ${outerColor} 100%)`;
    }

    renderAtmosphere(force = false) {
        if (!this.currentAtmosphere || !this.fillElement || !this.gradientElement || !this.vignetteElement) {
            return;
        }

        if (!this.isAtmosphereOverlayEnabled()) {
            if (this.frontRoot) {
                this.frontRoot.style.display = 'none';
            }
            this._atmosphereSignature = 'disabled';
            return;
        }

        if (this.frontRoot) {
            this.frontRoot.style.display = '';
        }

        const state = this.currentAtmosphere;

        // Only build the (allocation-heavy) signature when change detection is
        // actually wanted — forced calls (transitions write every frame anyway)
        // skip it and invalidate so the next unforced call re-establishes it.
        let signature = null;
        if (!force) {
            signature = JSON.stringify({
                fill: state.globalColor.map(value => Number(value.toFixed(3))),
                fillBlend: state.globalBlendMode,
                gradientEnabled: state.gradientEnabled,
                gradientOpacity: Number(state.gradientOpacity.toFixed(3)),
                gradientAngle: Number(state.gradientAngle.toFixed(2)),
                gradientOriginX: Number(state.gradientOriginX.toFixed(3)),
                gradientOriginY: Number(state.gradientOriginY.toFixed(3)),
                gradientSpan: Number(state.gradientSpan.toFixed(3)),
                stops: state.gradientStops.map(stop => [
                    Number(stop.position.toFixed(3)),
                    ...stop.color.map(value => Number(value.toFixed(3)))
                ]),
                vignette: state.vignetteColor.map(value => Number(value.toFixed(3))),
                vignetteOpacity: Number(state.vignetteOpacity.toFixed(3))
            });

            if (signature === this._atmosphereSignature) {
                return;
            }
        }

        this._atmosphereSignature = signature;
        this.fillElement.style.backgroundColor = MapEnvironmentManager.toRgbaString(state.globalColor);
        this.fillElement.style.mixBlendMode = state.globalBlendMode || 'multiply';

        this.gradientElement.style.backgroundImage = this.buildGradientCss(state);
        this.gradientElement.style.backgroundSize = `${Utility.clamp(state.gradientSpan * 100, 15, 300)}% 100%`;
        this.gradientElement.style.backgroundPosition = `${state.gradientOriginX * 100}% ${state.gradientOriginY * 100}%`;
        this.gradientElement.style.backgroundRepeat = 'no-repeat';
        this.gradientElement.style.mixBlendMode = state.gradientBlendMode || 'screen';
        this.gradientElement.style.opacity = state.gradientEnabled ? '1' : '0';

        this.vignetteElement.style.backgroundImage = this.buildVignetteCss(state);
        this.vignetteElement.style.opacity = `${Utility.clamp(state.vignetteOpacity, 0, 1)}`;
    }

    getViewportMetrics() {
        const bounds = this.syncLightingOverlayBounds();
        const zoom = this.gameMap?.camera?.zoomLevel || 1;
        const cameraX = this.gameMap?.camera?.posX || 0;
        const cameraY = this.gameMap?.camera?.posY || 0;
        const overscan = Math.max(0, Number(this.config?.lighting?.overscan ?? 64));
        const safeZoom = Math.max(zoom, 0.001);
        const viewportWidth = bounds?.width || 0;
        const viewportHeight = bounds?.height || 0;
        const viewportOffsetLeft = bounds?.offsetLeft || 0;
        const viewportOffsetTop = bounds?.offsetTop || 0;
        return {
            viewportWidth,
            viewportHeight,
            viewportOffsetLeft,
            viewportOffsetTop,
            zoom,
            cameraX,
            cameraY,
            overscan,
            worldLeft: ((viewportOffsetLeft - overscan) / safeZoom) - cameraX,
            worldTop: ((viewportOffsetTop - overscan) / safeZoom) - cameraY,
            worldRight: ((viewportOffsetLeft + viewportWidth + overscan) / safeZoom) - cameraX,
            worldBottom: ((viewportOffsetTop + viewportHeight + overscan) / safeZoom) - cameraY
        };
    }

    resizeLightingCanvases(view = null, force = false) {
        if (!this.lightingColorCanvas || !this.lightingDarknessCanvas) {
            return null;
        }

        const nextView = view || this.getViewportMetrics();
        const resolutionScale = Math.max(0.25, Number(this.config?.lighting?.resolutionScale ?? 0.5));
        const colorResolutionScale = Math.max(
            resolutionScale,
            Number(this.config?.lighting?.colorResolutionScale ?? 1)
        );
        const deviceScale = Math.max(1, window.devicePixelRatio || 1);
        const darknessCanvasScale = resolutionScale * deviceScale;
        const colorCanvasScale = colorResolutionScale * deviceScale;

        this._lightingCanvasScale = darknessCanvasScale;

        const resizeCanvas = (canvas, canvasScale) => {
            const targetWidth = Math.max(1, Math.ceil(nextView.viewportWidth * canvasScale));
            const targetHeight = Math.max(1, Math.ceil(nextView.viewportHeight * canvasScale));
            const needsResize = force ||
                canvas.width !== targetWidth ||
                canvas.height !== targetHeight ||
                canvas.style.width !== `${nextView.viewportWidth}px` ||
                canvas.style.height !== `${nextView.viewportHeight}px`;

            if (needsResize) {
                canvas.width = targetWidth;
                canvas.height = targetHeight;
                canvas.style.width = `${nextView.viewportWidth}px`;
                canvas.style.height = `${nextView.viewportHeight}px`;
            }
        };

        resizeCanvas(this.lightingColorCanvas, colorCanvasScale);
        resizeCanvas(this.lightingDarknessCanvas, darknessCanvasScale);

        if (this.lightingColorContext) {
            this.lightingColorContext.setTransform(colorCanvasScale, 0, 0, colorCanvasScale, 0, 0);
        }
        if (this.lightingDarknessContext) {
            this.lightingDarknessContext.setTransform(darknessCanvasScale, 0, 0, darknessCanvasScale, 0, 0);
        }

        return nextView;
    }

    worldToScreenPoint(worldX, worldY, view = this.getViewportMetrics()) {
        return {
            x: ((worldX + view.cameraX) * view.zoom) - view.viewportOffsetLeft,
            y: ((worldY + view.cameraY) * view.zoom) - view.viewportOffsetTop
        };
    }

    worldToScreenRect(bounds, view = this.getViewportMetrics()) {
        const topLeft = this.worldToScreenPoint(bounds.x, bounds.y, view);
        return {
            x: topLeft.x,
            y: topLeft.y,
            width: bounds.width * view.zoom,
            height: bounds.height * view.zoom
        };
    }

    intersectsView(bounds, view = this.getViewportMetrics(), pad = 0) {
        const left = bounds.x;
        const top = bounds.y;
        const right = bounds.x + bounds.width;
        const bottom = bounds.y + bounds.height;
        return right >= view.worldLeft - pad &&
            left <= view.worldRight + pad &&
            bottom >= view.worldTop - pad &&
            top <= view.worldBottom + pad;
    }

    collectAllLights() {
        return (this.gameMap?.objects || [])
            .filter(object => object?.isLightSource?.())
            .map(object => {
                const config = object.getLightSourceConfig?.();
                if (!config) {
                    return null;
                }

                const center = object.getCenterPoint?.('collider') || object.getCenterPoint?.() || {
                    x: object.posX + (object.size?.width ?? 0) / 2,
                    y: object.posY + (object.size?.height ?? 0) / 2
                };
                const room = this.findRoomContainingPoint(center.x, center.y);

                return {
                    object,
                    config,
                    center,
                    roomId: String(object.getConfig?.('lighting.roomId', room?.id || '') || room?.id || '').toLowerCase()
                };
            })
            .filter(Boolean);
    }

    collectVisibleLights(view = this.getViewportMetrics(), allLights = this.collectAllLights()) {
        const lights = allLights
            .filter(light => {
                const radius = Number(light.config?.radius || 0);
                return (
                    light.center.x + radius >= view.worldLeft &&
                    light.center.x - radius <= view.worldRight &&
                    light.center.y + radius >= view.worldTop &&
                    light.center.y - radius <= view.worldBottom
                );
            })
            .sort((a, b) => Number(b.config?.hero === true) - Number(a.config?.hero === true));

        return lights;
    }

    collectVisibleBlockers(view = this.getViewportMetrics()) {
        const objects = this.gameMap?.gridSystem?.activeObjects
            ? Array.from(this.gameMap.gridSystem.activeObjects)
            : (this.gameMap?.objects || []);

        return objects
            .filter(object => object?.isLightBlocking?.())
            .map(object => object.getLightBlockerGeometry?.())
            .filter(Boolean)
            .filter(geometry => this.intersectsView({
                x: geometry.left,
                y: geometry.top,
                width: geometry.width,
                height: geometry.height
            }, view, 24));
    }

    findRoomContainingPoint(worldX, worldY) {
        return this.roomVolumes.find(room =>
            worldX >= room.bounds.x &&
            worldX <= room.bounds.x + room.bounds.width &&
            worldY >= room.bounds.y &&
            worldY <= room.bounds.y + room.bounds.height
        ) || null;
    }

    deriveRoomLightingState(allLights, darknessFactor) {
        const roomState = new Map();

        this.roomVolumes.forEach(room => {
            const mode = room.lighting.mode || 'mixed';
            const baseFloor = mode === 'local'
                ? 0
                : room.lighting.ambientFloor * darknessFactor;
            roomState.set(room.id, {
                room,
                lift: Utility.clamp(baseFloor, 0, room.lighting.ambientCeiling),
                colorAlpha: Utility.clamp(baseFloor * 0.42, 0, 0.42)
            });
        });

        allLights.forEach(light => {
            if (!light.roomId || !roomState.has(light.roomId)) {
                return;
            }

            const target = roomState.get(light.roomId);
            const mode = target.room.lighting.mode || 'mixed';
            const modeMultiplier = mode === 'filled' ? 1.08 : (mode === 'local' ? 0.42 : 0.78);
            const contribution = Utility.clamp(
                light.config.roomFill * light.config.intensity * darknessFactor * modeMultiplier,
                0,
                target.room.lighting.ambientCeiling
            );
            target.lift = Utility.clamp(target.lift + contribution, 0, target.room.lighting.ambientCeiling);
            target.colorAlpha = Utility.clamp(target.colorAlpha + (contribution * 0.56), 0, 0.52);
        });

        this.lightOpenings.forEach(opening => {
            const roomA = roomState.get(opening.roomA);
            const roomB = roomState.get(opening.roomB);
            if (!roomA || !roomB) {
                return;
            }

            const spill = Utility.clamp(opening.spillFactor, 0, 1);
            const nextA = Utility.clamp(roomA.lift + (roomB.lift * spill), 0, roomA.room.lighting.ambientCeiling);
            const nextB = Utility.clamp(roomB.lift + (roomA.lift * spill), 0, roomB.room.lighting.ambientCeiling);
            roomA.lift = Math.max(roomA.lift, nextA);
            roomB.lift = Math.max(roomB.lift, nextB);
            roomA.colorAlpha = Utility.clamp(Math.max(roomA.colorAlpha, roomB.colorAlpha * spill), 0, 0.52);
            roomB.colorAlpha = Utility.clamp(Math.max(roomB.colorAlpha, roomA.colorAlpha * spill), 0, 0.52);
        });

        return roomState;
    }

    buildLightingSignature(view, lightingState, roomState, visibleLights, blockers) {
        return JSON.stringify({
            view: [
                Math.round(view.viewportWidth),
                Math.round(view.viewportHeight),
                Math.round(view.viewportOffsetLeft),
                Math.round(view.viewportOffsetTop),
                Number(view.zoom.toFixed(3)),
                Number(view.cameraX.toFixed(2)),
                Number(view.cameraY.toFixed(2))
            ],
            minutes: this.getMinutesFromTimeData(this.getTimeData()),
            cycleMode: lightingState?.cycleMode || '',
            cycleProgress: Number((lightingState?.positionProgress || 0).toFixed(3)),
            bandStrength: Number((lightingState?.bandStrength || 0).toFixed(3)),
            darkness: Number((lightingState?.darknessFactor || 0).toFixed(3)),
            rooms: Array.from(roomState.values()).map(entry => [
                entry.room.id,
                Number(entry.lift.toFixed(3)),
                Number(entry.colorAlpha.toFixed(3))
            ]),
            lights: visibleLights.map(light => [
                light.object?.id || '',
                Number(light.center.x.toFixed(1)),
                Number(light.center.y.toFixed(1)),
                Number(light.config.radius.toFixed(1)),
                Number(light.config.intensity.toFixed(2)),
                light.config.color,
                light.roomId,
                light.config.castsShadows === true
            ]),
            blockers: blockers.map(blocker => [
                Number(blocker.left.toFixed(1)),
                Number(blocker.top.toFixed(1)),
                Number(blocker.width.toFixed(1)),
                Number(blocker.height.toFixed(1))
            ])
        });
    }

    clearLightingCanvases(view) {
        if (this.lightingColorContext) {
            this.lightingColorContext.clearRect(0, 0, view.viewportWidth, view.viewportHeight);
        }
        if (this.lightingDarknessContext) {
            this.lightingDarknessContext.clearRect(0, 0, view.viewportWidth, view.viewportHeight);
        }
    }

    renderLighting(force = false) {
        if (!this.lightingOverlay || !this.lightingColorContext || !this.lightingDarknessContext) {
            return;
        }

        // Steady-state gate — the full pass below measures rects and scans every
        // map object for lights, which is far too heavy to run per frame when
        // nothing can have changed. Viewport geometry only moves with the camera
        // (window resize forces a refresh via _boundResize), and light/room
        // toggles are caught by a low-cadence periodic re-check instead.
        const camera = this.gameMap?.camera;
        const camX = camera?.posX ?? 0;
        const camY = camera?.posY ?? 0;
        const camZoom = camera?.zoomLevel ?? 1;
        const minutes = this.getMinutesFromTimeData(this.getTimeData());
        const now = performance.now();
        const cameraChanged = camX !== this._lastLightingCamX ||
            camY !== this._lastLightingCamY ||
            camZoom !== this._lastLightingCamZoom;
        const refreshDue = now >= (this._nextLightingRefreshAt ?? 0);

        if (!force && !cameraChanged && !refreshDue &&
            minutes === this._lastLightingMinutes &&
            !this.atmosphereTransitionActive) {
            return;
        }

        this._lastLightingCamX = camX;
        this._lastLightingCamY = camY;
        this._lastLightingCamZoom = camZoom;
        this._lastLightingMinutes = minutes;
        this._nextLightingRefreshAt = now + (this.config?.lighting?.idleRefreshMs ?? 150);

        const view = this.getViewportMetrics();
        if (view.viewportWidth <= 0 || view.viewportHeight <= 0) {
            this.lightingOverlay.style.opacity = '0';
            return;
        }

        this.resizeLightingCanvases(view);

        const lightingConfig = this.config?.lighting || {};
        if (lightingConfig.enabled === false) {
            this.clearLightingCanvases(view);
            this.lightingOverlay.style.opacity = '0';
            return;
        }

        const timeData = this.getTimeData();
        const lightingState = this.resolveLightingPeriodState(timeData);
        const darknessFactor = lightingState.darknessFactor;
        const allLights = this.collectAllLights();
        const visibleLights = this.collectVisibleLights(view, allLights);
        const blockers = this.collectVisibleBlockers(view);
        const roomState = this.deriveRoomLightingState(allLights, darknessFactor);

        const signature = this.buildLightingSignature(view, lightingState, roomState, visibleLights, blockers);
        if (!force && signature === this._lightingSignature && !this.atmosphereTransitionActive) {
            return;
        }

        this._lightingSignature = signature;
        this.clearLightingCanvases(view);

        const darknessOpacity = darknessFactor * lightingState.darknessOpacityMax;
        const darknessColor = MapEnvironmentManager.scaleColorAlpha(
            lightingState.darknessColor,
            darknessOpacity
        );

        const darkCtx = this.lightingDarknessContext;
        const colorCtx = this.lightingColorContext;
        this.drawAmbientDarkness(darkCtx, view, lightingState, darknessColor);

        roomState.forEach(entry => {
            if (entry.lift <= 0.01 || !this.intersectsView(entry.room.bounds, view, 24)) {
                return;
            }
            const screenRect = this.worldToScreenRect(entry.room.bounds, view);
            this.drawFeatheredRectAlpha(
                darkCtx,
                screenRect.x,
                screenRect.y,
                screenRect.width,
                screenRect.height,
                entry.room.lighting.feather,
                Utility.clamp(entry.lift, 0, 1)
            );
        });

        visibleLights.forEach(light => {
            this.drawRadialLightCutout(darkCtx, light, view, darknessFactor);
        });

        this.drawLightShadows(darkCtx, visibleLights, blockers, view, darknessFactor);

        colorCtx.globalCompositeOperation = 'source-over';
        this.drawSunCycleColorBand(colorCtx, view, lightingState);

        roomState.forEach(entry => {
            if (entry.colorAlpha <= 0.01 || !this.intersectsView(entry.room.bounds, view, 24)) {
                return;
            }
            const screenRect = this.worldToScreenRect(entry.room.bounds, view);
            const roomColor = MapEnvironmentManager.scaleColorAlpha(
                entry.room.lighting.fillColor,
                entry.colorAlpha
            );
            this.drawFeatheredRectColor(
                colorCtx,
                screenRect.x,
                screenRect.y,
                screenRect.width,
                screenRect.height,
                entry.room.lighting.feather,
                roomColor
            );
        });

        const ditherConfig = lightingConfig.dither || {};
        if (ditherConfig.enabled && Number(ditherConfig.pixelSize) >= 1) {
            const fillAlpha = Math.round(darknessOpacity * 255);
            // Scale pixel size with zoom so the dither pattern has consistent game-world size.
            const effectivePixelSize = Math.max(1, Math.round(
                Number(ditherConfig.pixelSize) * view.zoom
            ));
            this.drawDitherPass(darkCtx, this.lightingDarknessCanvas, effectivePixelSize, fillAlpha);
        }

        const hasVisibleEffect = darknessOpacity > 0.01 ||
            lightingState.bandStrength > 0.01 ||
            Array.from(roomState.values()).some(entry => entry.lift > 0.01);
        this.lightingOverlay.style.opacity = hasVisibleEffect ? '1' : '0';
    }

    drawDitherPass(ctx, canvas, pixelSize, fillAlpha = 255) {
        if (canvas.width <= 0 || canvas.height <= 0 || fillAlpha < 8) {
            return;
        }

        const ps = Math.max(1, Math.round(pixelSize));
        const w = canvas.width;
        const h = canvas.height;

        // clearMax (65% of fill): below this the area is lit — force to 0 so no smooth gradient
        //   leaks through when zoomed in. Covers light interiors down to ~35% intensity lights.
        // solidMin (fill - 4): at or above this is solid darkness — force to fillAlpha.
        //   Prevents a smooth dark rim from appearing outside the dithered band.
        const clearMax = Math.round(fillAlpha * 0.65);
        const solidMin = Math.max(clearMax + 16, fillAlpha - 4);

        const imageData = ctx.getImageData(0, 0, w, h);
        const px = imageData.data;

        // Bayer 4×4 ordered dither matrix
        const B = [
             0, 128,  32, 160,
            192,  64, 224,  96,
             48, 176,  16, 144,
            240, 112, 208,  80
        ];

        for (let y = 0; y < h; y++) {
            const row = (Math.floor(y / ps) & 3) << 2;
            for (let x = 0; x < w; x++) {
                const i = (y * w + x) << 2;
                const a = px[i + 3];
                if (a === 0) continue;
                if (a <= clearMax) { px[i + 3] = 0; continue; }      // force clear — no smooth halo
                if (a >= solidMin) { px[i + 3] = fillAlpha; continue; } // force solid — no smooth rim
                const col = Math.floor(x / ps) & 3;
                const normalized = Math.round((a - clearMax) / (solidMin - clearMax) * 255);
                px[i + 3] = normalized > B[row | col] ? fillAlpha : 0;
            }
        }

        ctx.putImageData(imageData, 0, 0);
    }

    drawAmbientDarkness(ctx, view, lightingState, darknessColor) {
        ctx.globalCompositeOperation = 'source-over';

        if (!lightingState || !darknessColor) {
            return;
        }

        const mode = lightingState.cycleMode;
        if (mode !== 'sunrise' && mode !== 'sunset') {
            ctx.fillStyle = MapEnvironmentManager.toRgbaString(darknessColor);
            ctx.fillRect(0, 0, view.viewportWidth, view.viewportHeight);
            return;
        }

        const bandMetrics = this.getSunBandMetrics(view, lightingState);
        ctx.fillStyle = MapEnvironmentManager.toRgbaString(darknessColor);
        ctx.fillRect(0, 0, view.viewportWidth, view.viewportHeight);

        ctx.save();
        ctx.globalCompositeOperation = 'destination-out';
        const gradient = ctx.createLinearGradient(bandMetrics.left, 0, bandMetrics.right, 0);
        // Left = night side (keep darkness). Right = day side (erase darkness).
        // Works for both sunset (left→right sweep) and sunrise (right→left sweep) because the
        // preset startX/endX encode the travel direction — the clamped gradient end always
        // corresponds to the correct state when the band is fully off-screen.
        gradient.addColorStop(0, 'rgba(0, 0, 0, 0)');
        gradient.addColorStop(0.3, 'rgba(0, 0, 0, 0.06)');
        gradient.addColorStop(0.52, 'rgba(0, 0, 0, 0.28)');
        gradient.addColorStop(0.7, 'rgba(0, 0, 0, 0.66)');
        gradient.addColorStop(0.85, 'rgba(0, 0, 0, 0.92)');
        gradient.addColorStop(1, 'rgba(0, 0, 0, 1)');
        ctx.fillStyle = gradient;
        ctx.fillRect(0, 0, view.viewportWidth, view.viewportHeight);

        ctx.restore();
    }

    drawSunCycleColorBand(ctx, view, lightingState) {
        if (!this.isAtmosphereOverlayEnabled()) {
            return;
        }

        const bandConfig = lightingState?.bandConfig || null;
        const bandStrength = Utility.clamp(Number(lightingState?.bandStrength ?? 0), 0, 1);
        if (!bandConfig || bandStrength <= 0.001) {
            return;
        }

        const stops = Array.isArray(bandConfig.stops) ? bandConfig.stops : [];
        if (stops.length === 0) {
            return;
        }

        const bandMetrics = this.getSunBandMetrics(view, lightingState);
        const opacityScale = Utility.clamp(Number(bandConfig.bandOpacity ?? 1) * bandStrength, 0, 1);
        const gradient = ctx.createLinearGradient(bandMetrics.left, 0, bandMetrics.right, 0);

        stops.forEach(stop => {
            const color = MapEnvironmentManager.parseColor(stop.color || 'rgba(0, 0, 0, 0)');
            color[3] = Utility.clamp(color[3] * opacityScale, 0, 1);
            gradient.addColorStop(
                Utility.clamp(Number(stop.position ?? 0), 0, 1),
                MapEnvironmentManager.toRgbaString(color)
            );
        });

        ctx.save();
        ctx.globalCompositeOperation = 'source-over';
        ctx.fillStyle = gradient;
        ctx.fillRect(0, 0, view.viewportWidth, view.viewportHeight);
        ctx.restore();
    }

    getSunBandMetrics(view, lightingState) {
        const bandConfig = lightingState?.bandConfig || {};
        const progress = Utility.clamp(Number(lightingState?.positionProgress ?? 0), 0, 1);
        const centerXRatio = Utility.lerp(
            Number(bandConfig.startX ?? 0.5),
            Number(bandConfig.endX ?? 0.5),
            progress
        );
        const span = Utility.lerp(
            Math.max(0.25, Number(bandConfig.startSpan ?? bandConfig.span ?? 0.8)),
            Math.max(0.25, Number(bandConfig.endSpan ?? bandConfig.span ?? 0.8)),
            progress
        );
        const centerX = centerXRatio * view.viewportWidth;
        const halfWidth = Math.max(220, view.viewportWidth * span * 0.6);

        return {
            centerX,
            halfWidth,
            left: centerX - halfWidth,
            right: centerX + halfWidth
        };
    }

    drawFeatheredRectAlpha(ctx, x, y, width, height, feather, alpha) {
        const clampedAlpha = Utility.clamp(alpha, 0, 1);
        if (clampedAlpha <= 0 || width <= 0 || height <= 0) {
            return;
        }

        const f = Math.max(0, Math.min(feather, width / 2, height / 2));
        const innerX = x + f;
        const innerY = y + f;
        const innerWidth = Math.max(0, width - (f * 2));
        const innerHeight = Math.max(0, height - (f * 2));

        ctx.save();
        ctx.globalCompositeOperation = 'destination-out';

        if (innerWidth > 0 && innerHeight > 0) {
            ctx.fillStyle = `rgba(0, 0, 0, ${clampedAlpha})`;
            ctx.fillRect(innerX, innerY, innerWidth, innerHeight);
        }

        if (f > 0) {
            this.drawFeatherBands(ctx, x, y, width, height, f, `rgba(0, 0, 0, ${clampedAlpha})`, true);
        }

        ctx.restore();
    }

    drawFeatheredRectColor(ctx, x, y, width, height, feather, color) {
        if (width <= 0 || height <= 0) {
            return;
        }

        const rgba = MapEnvironmentManager.parseColor(color);
        if (rgba[3] <= 0) {
            return;
        }

        const f = Math.max(0, Math.min(feather, width / 2, height / 2));
        const innerX = x + f;
        const innerY = y + f;
        const innerWidth = Math.max(0, width - (f * 2));
        const innerHeight = Math.max(0, height - (f * 2));

        ctx.save();
        if (innerWidth > 0 && innerHeight > 0) {
            ctx.fillStyle = MapEnvironmentManager.toRgbaString(rgba);
            ctx.fillRect(innerX, innerY, innerWidth, innerHeight);
        }

        if (f > 0) {
            this.drawFeatherBands(ctx, x, y, width, height, f, MapEnvironmentManager.toRgbaString(rgba), false);
        }
        ctx.restore();
    }

    drawFeatherBands(ctx, x, y, width, height, feather, color, destinationOut) {
        const transparent = destinationOut ? 'rgba(0, 0, 0, 0)' : MapEnvironmentManager.toRgbaString([...MapEnvironmentManager.parseColor(color).slice(0, 3), 0]);

        const topGradient = ctx.createLinearGradient(0, y, 0, y + feather);
        topGradient.addColorStop(0, transparent);
        topGradient.addColorStop(1, color);
        ctx.fillStyle = topGradient;
        ctx.fillRect(x + feather, y, Math.max(0, width - (feather * 2)), feather);

        const bottomGradient = ctx.createLinearGradient(0, y + height - feather, 0, y + height);
        bottomGradient.addColorStop(0, color);
        bottomGradient.addColorStop(1, transparent);
        ctx.fillStyle = bottomGradient;
        ctx.fillRect(x + feather, y + height - feather, Math.max(0, width - (feather * 2)), feather);

        const leftGradient = ctx.createLinearGradient(x, 0, x + feather, 0);
        leftGradient.addColorStop(0, transparent);
        leftGradient.addColorStop(1, color);
        ctx.fillStyle = leftGradient;
        ctx.fillRect(x, y + feather, feather, Math.max(0, height - (feather * 2)));

        const rightGradient = ctx.createLinearGradient(x + width - feather, 0, x + width, 0);
        rightGradient.addColorStop(0, color);
        rightGradient.addColorStop(1, transparent);
        ctx.fillStyle = rightGradient;
        ctx.fillRect(x + width - feather, y + feather, feather, Math.max(0, height - (feather * 2)));

        const corners = [
            { cx: x + feather, cy: y + feather, start: Math.PI, end: 1.5 * Math.PI },
            { cx: x + width - feather, cy: y + feather, start: 1.5 * Math.PI, end: 0 },
            { cx: x + feather, cy: y + height - feather, start: 0.5 * Math.PI, end: Math.PI },
            { cx: x + width - feather, cy: y + height - feather, start: 0, end: 0.5 * Math.PI }
        ];

        corners.forEach(corner => {
            const gradient = ctx.createRadialGradient(corner.cx, corner.cy, 0, corner.cx, corner.cy, feather);
            gradient.addColorStop(0, color);
            gradient.addColorStop(1, transparent);
            ctx.beginPath();
            ctx.moveTo(corner.cx, corner.cy);
            ctx.arc(corner.cx, corner.cy, feather, corner.start, corner.end);
            ctx.closePath();
            ctx.fillStyle = gradient;
            ctx.fill();
        });
    }

    drawRadialLightCutout(ctx, light, view, darknessFactor) {
        const screenPoint = this.worldToScreenPoint(light.center.x, light.center.y, view);
        const radius = Math.max(6, light.config.radius * view.zoom);
        const alpha = Utility.clamp(light.config.intensity * darknessFactor, 0, 1);
        const gradient = ctx.createRadialGradient(screenPoint.x, screenPoint.y, 0, screenPoint.x, screenPoint.y, radius);
        gradient.addColorStop(0, `rgba(0, 0, 0, ${alpha})`);
        gradient.addColorStop(0.55, `rgba(0, 0, 0, ${alpha * 0.65})`);
        gradient.addColorStop(1, 'rgba(0, 0, 0, 0)');

        ctx.save();
        ctx.globalCompositeOperation = 'destination-out';
        ctx.fillStyle = gradient;
        ctx.beginPath();
        ctx.arc(screenPoint.x, screenPoint.y, radius, 0, Math.PI * 2);
        ctx.fill();
        ctx.restore();
    }

    drawLightShadows(ctx, visibleLights, blockers, view, darknessFactor) {
        const heroLightLimit = Math.max(0, Number(this.config?.lighting?.heroLightLimit ?? 3));
        const shadowStrength = Utility.clamp(Number(this.config?.lighting?.shadowStrength ?? 0.32) * darknessFactor, 0, 1);
        if (shadowStrength <= 0.01 || heroLightLimit === 0 || blockers.length === 0) {
            return;
        }

        const darknessBase = MapEnvironmentManager.parseColor(this.config?.lighting?.darknessColor || 'rgba(18, 18, 28, 1)');
        darknessBase[3] = shadowStrength;
        const shadowColor = MapEnvironmentManager.toRgbaString(darknessBase);
        const heroLights = visibleLights.filter(light => light.config.castsShadows === true).slice(0, heroLightLimit);

        heroLights.forEach(light => {
            const lightScreen = this.worldToScreenPoint(light.center.x, light.center.y, view);
            const lightRadius = Math.max(1, light.config.radius * view.zoom);
            blockers.forEach(blocker => {
                const blockerCenterX = blocker.left + (blocker.width / 2);
                const blockerCenterY = blocker.top + (blocker.height / 2);
                const dx = blockerCenterX - light.center.x;
                const dy = blockerCenterY - light.center.y;
                const distance = Math.hypot(dx, dy);
                if (distance > light.config.radius + Math.max(blocker.width, blocker.height)) {
                    return;
                }

                const shadowEdge = this.getShadowEdgeForBlocker(blocker, light.center);
                if (!shadowEdge) {
                    return;
                }

                const p1 = this.worldToScreenPoint(shadowEdge.p1.x, shadowEdge.p1.y, view);
                const p2 = this.worldToScreenPoint(shadowEdge.p2.x, shadowEdge.p2.y, view);
                const extrudeDistance = lightRadius * 3.2;
                const v1 = this.normalizeVector(p1.x - lightScreen.x, p1.y - lightScreen.y);
                const v2 = this.normalizeVector(p2.x - lightScreen.x, p2.y - lightScreen.y);
                const e1 = { x: p1.x + (v1.x * extrudeDistance), y: p1.y + (v1.y * extrudeDistance) };
                const e2 = { x: p2.x + (v2.x * extrudeDistance), y: p2.y + (v2.y * extrudeDistance) };

                ctx.save();
                ctx.globalCompositeOperation = 'source-over';
                ctx.fillStyle = shadowColor;
                ctx.beginPath();
                ctx.moveTo(p1.x, p1.y);
                ctx.lineTo(p2.x, p2.y);
                ctx.lineTo(e2.x, e2.y);
                ctx.lineTo(e1.x, e1.y);
                ctx.closePath();
                ctx.fill();
                ctx.restore();
            });
        });
    }

    getShadowEdgeForBlocker(blocker, lightCenter) {
        const centerX = blocker.left + (blocker.width / 2);
        const centerY = blocker.top + (blocker.height / 2);
        const dx = centerX - lightCenter.x;
        const dy = centerY - lightCenter.y;

        if (Math.abs(dx) >= Math.abs(dy)) {
            if (dx >= 0) {
                return {
                    p1: { x: blocker.right, y: blocker.top },
                    p2: { x: blocker.right, y: blocker.bottom }
                };
            }

            return {
                p1: { x: blocker.left, y: blocker.top },
                p2: { x: blocker.left, y: blocker.bottom }
            };
        }

        if (dy >= 0) {
            return {
                p1: { x: blocker.left, y: blocker.bottom },
                p2: { x: blocker.right, y: blocker.bottom }
            };
        }

        return {
            p1: { x: blocker.left, y: blocker.top },
            p2: { x: blocker.right, y: blocker.top }
        };
    }

    normalizeVector(x, y) {
        const length = Math.max(0.0001, Math.hypot(x, y));
        return {
            x: x / length,
            y: y / length
        };
    }

    dispose() {
        this._subscriptions.forEach(subscription => {
            this.timeManager?.unsubscribe?.(subscription.eventName, subscription.callback);
        });
        this._subscriptions = [];

        window.removeEventListener('resize', this._boundResize);

        this.lightingOverlay?.remove();
        this.lightingOverlay = null;
        this.lightingColorCanvas = null;
        this.lightingDarknessCanvas = null;
        this.lightingColorContext = null;
        this.lightingDarknessContext = null;
        this._lightingBounds = null;

        this.fillElement?.remove?.();
        this.gradientElement?.remove?.();
        this.vignetteElement?.remove?.();
        this.frontRoot?.remove?.();
        this.backRoot?.remove?.();
        this.frontLayer = null;
        this.backLayer = null;
        this.frontRoot = null;
        this.backRoot = null;
        this.fillElement = null;
        this.gradientElement = null;
        this.vignetteElement = null;

        this.roomVolumes = [];
        this.lightOpenings = [];
        this.config = null;
        this.mapData = null;
        this._isInitialized = false;
    }
}
;
